import{n as m$1,t as l$1}from"./chunk-Da4-SChG.js";function y(e=(/* @__PURE__ */ new Date()).getFullYear(),r=`en`){let a=Number.isFinite(e)?Math.max(2026,Math.trunc(e)):2026;return`\xA9 ${a===2026?String(2026):`2026 - ${a}`} RadioBee. ${r===`ta`?`அனைத்து உரிமைகளும் பாதுகாக்கப்பட்டவை.`:r===`sa`?`सर्वे अधिकाराः सुरक्षिताः।`:`All rights reserved.`}`}var d={privacy:{title:`தனியுரிமைக் கொள்கை`,summary:`RadioBee உங்கள் சாதனத்தில் சேமிக்கும் தகவல்கள், மூன்றாம் தரப்பு ஒலிபரப்புச் சேவைகளுடன் பகிரப்படக்கூடிய தகவல்கள், அச்சேவைகள் மீதான எங்கள் கட்டுப்பாட்டின் வரம்புகள் ஆகியவற்றை இந்தக் கொள்கை விளக்குகிறது. நடைமுறைக்கு வந்த நாள்: 17 நவம்பர் 2026.`,sections:[{heading:`1. வரம்பும் சேவையும்`,paragraphs:[`RadioBee என்பது இணைய வானொலி நிலையங்களைக் கண்டறிந்து கேட்க உதவும் செயலியாகும். இந்தக் கொள்கை RadioBee இணையதளத்திற்கும் செயலி வழங்கும் அம்சங்களுக்கும் பொருந்தும். RadioBee மூலம் நீங்கள் அணுகும் ஒலிபரப்பாளர்கள், ஒலிபரப்புச் சேவை வழங்குநர்கள், இயங்குதளங்கள், செயலிக் கடைகள் அல்லது பிற இணையதளங்களின் தனித் தனியுரிமை அறிவிப்புகளுக்கோ நடைமுறைகளுக்கோ இது மாற்றாகாது.`,`மூன்றாம் தரப்பினரின் ஒலி ஒலிபரப்புகளைப் பட்டியலிட்டு இயக்கும் சேவையாக RadioBee செயல்படுகிறது. ஒலிபரப்பாளர்களும் அவர்களது சேவை வழங்குநர்களும் தங்கள் சேவையகங்களுக்கு வரும் இணையக் கோரிக்கைகளையும் தொடர்புடைய தகவல்களையும் எவ்வாறு கையாள்வது என்பதைத் தாங்களே தீர்மானிக்கின்றனர்.`]},{heading:`2. செயலியில் சேமிக்கப்படும் தகவல்கள்`,paragraphs:[`செயலி, உலாவி அல்லது இயங்குதளத்தின் சேமிப்பகத்தைப் பயன்படுத்தி உங்கள் விருப்பங்களையும் செயல்பாட்டிற்குத் தேவையான தகவல்களையும் சாதனத்திலேயே சேமிக்கிறது. நீங்கள் பயன்படுத்தும் அம்சங்களைப் பொறுத்து, பிடித்த நிலையங்கள், இடைமுக மொழி, தோற்ற அமைப்பு, முகப்புப் பக்க நிலையத் தேர்வுகள், தற்காலிகமாகச் சேமிக்கப்பட்ட வானொலிப் பட்டியல் தகவல்கள் ஆகியவை இதில் அடங்கலாம்.`,`இணையதளத் தரவை அழித்தல், உலாவியை மாற்றுதல் அல்லது செயலியை நிறுவல் நீக்குதல் போன்ற செயல்களால் சாதனத்தில் சேமிக்கப்பட்ட விருப்பங்கள் நீங்கலாம். உள்ளூர் சேமிப்பகம் கிடைப்பதும் அதில் தரவு தொடர்ந்து இருப்பதும் உலாவி மற்றும் இயங்குதளக் கட்டுப்பாடுகளைப் பொறுத்தது.`]},{heading:`3. வானொலி கேட்பதும் மூன்றாம் தரப்பு இணையக் கோரிக்கைகளும்`,paragraphs:[`நீங்கள் ஒரு நிலையத்தை இயக்கும்போது, உங்கள் சாதனம் அந்த ஒலிபரப்பாளர் அல்லது ஒலிபரப்புச் சேவை வழங்குநருடன் இணையம் வழியாக இணைகிறது. உங்கள் IP முகவரி, சாதனம் மற்றும் உலாவி விவரங்கள், கோரிக்கை நேரம், ஒலிபரப்பு URL போன்ற தொழில்நுட்பத் தகவல்களை அவர்கள் பெறக்கூடும். அவர்கள் மேற்கொள்ளும் தகவல் சேகரிப்பு, குக்கீ பயன்பாடு, பதிவேடு பராமரிப்பு, நிலப்பகுதி அடிப்படையிலான கட்டுப்பாடுகள் மற்றும் தரவு வைத்திருக்கும் நடைமுறைகள் RadioBee-யின் கட்டுப்பாட்டிற்கு அப்பாற்பட்டவை.`,`வானொலிப் பட்டியல் மற்றும் செயலிக்கான வளங்கள் GitHub Pages அல்லது அமைக்கப்பட்ட பிற சேவை உள்கட்டமைப்புகளிலிருந்து பெறப்படலாம். அவற்றை வழங்கும் நிறுவனங்கள் தங்களது கொள்கைகளின்படி தொழில்நுட்பக் கோரிக்கைப் பதிவுகளைச் செயலாக்கலாம்.`]},{heading:`4. சாதனச் சேமிப்பகமும் விருப்பங்களும்`,paragraphs:[`RadioBee உங்கள் விருப்பங்களை நினைவில் வைத்துக்கொள்ளவும், கிடைக்கும் இடங்களில் நிலையப் பட்டியல் தகவல்களைத் தற்காலிகமாகச் சேமிக்கவும் சாதனத்தின் உள்ளூர் சேமிப்பகத்தைப் பயன்படுத்துகிறது. இதனால் பிடித்த நிலையங்கள் மற்றும் இடைமுக அமைப்புகள் போன்ற அம்சங்கள் அடுத்தடுத்த பயன்பாடுகளிலும் செயல்பட முடிகிறது.`,`உங்கள் அமைப்புகள், சேமிப்பிட வரம்புகள், தனியுரிமை முறைகள் அல்லது பராமரிப்பு நடவடிக்கைகள் காரணமாக உலாவியோ இயங்குதளமோ சேமித்த தகவல்களை நீக்கலாம். சாதனத்தில் சேமித்த விருப்பங்கள் காலவரையின்றி கிடைக்கும் என்று RadioBee உத்தரவாதம் அளிக்க முடியாது.`]},{heading:`5. நீங்கள் விருப்பத்துடன் சமர்ப்பிக்கும் தகவல்கள்`,paragraphs:[`RadioBee-யின் தொடர்புகொள்ளும் படிவம் மூன்றாம் தரப்புச் சேவையான Google Forms மூலம் சமர்ப்பிக்கப்படுகிறது. நீங்கள் படிவத்தைச் சமர்ப்பித்தால், பெயர், மின்னஞ்சல், விருப்பப்பட்டால் தொலைபேசி எண், தொடர்புகொள்வதன் நோக்கம், செய்தி, விருப்பப்பட்டால் நிலைய விவரங்கள் ஆகியவை செயலாக்கத்திற்காக Google-க்கு அனுப்பப்பட்டு RadioBee படிவ நிர்வாகி அணுகும் வகையில் கிடைக்கும். படிவப் பதிவுகள் RadioBee உலாவி விருப்பங்களாகச் சேமிக்கப்படுவதில்லை.`,`Google தனது விதிமுறைகள் மற்றும் தனியுரிமை நடைமுறைகளின்படி படிவப் பதிவுகளைச் செயலாக்குகிறது. கேள்வி அனுப்புவதும் சமர்ப்பிப்பதற்கு ஒப்புதல் அளிப்பதும் உங்கள் விருப்பம். பாதுகாப்பான தொடர்பு வழி தனியாக ஒப்புக்கொள்ளப்படாத வரை கடவுச்சொற்கள், அடையாள ஆவணங்கள், முக்கிய ஒப்பந்தத் தகவல்கள் அல்லது பிற ரகசியப் பொருட்களை அனுப்ப வேண்டாம்.`]},{heading:`6. குக்கீகள், பயன்பாட்டுப் பகுப்பாய்வு மற்றும் விளம்பரங்கள்`,paragraphs:[`மேலே விளக்கியபடி செயலியின் செயல்பாட்டிற்காக RadioBee சாதன மற்றும் உலாவிச் சேமிப்பகத்தைப் பயன்படுத்துகிறது. மூன்றாம் தரப்பு ஒலிபரப்புச் சேவை வழங்குநர்கள், உலாவிகள், இயங்குதளங்கள் அல்லது சேவை வழங்குநர்கள் எவரும் குக்கீகள், பயன்பாட்டுப் பகுப்பாய்வு, விளம்பரத் தொழில்நுட்பங்கள் அல்லது பதிவேடுகளைப் பயன்படுத்துவதில்லை என்று இக்கொள்கை உறுதி அளிப்பதில்லை.`,`பின்னர் RadioBee தனக்கான பயன்பாட்டுப் பகுப்பாய்வு, விளம்பர ஒருங்கிணைப்புகள், பயனர் அடையாளச் சரிபார்ப்பு அல்லது சேவையகத்தில் இயங்கும் வேறு தொடர்பு அமைப்பைச் சேர்த்தால், அவ்வம்சங்களையும் சட்டப்படி தேவைப்படும் தெரிவுகள் அல்லது அறிவிப்புகளையும் விளக்க இந்தக் கொள்கை மறுஆய்வு செய்யப்பட்டு புதுப்பிக்கப்பட வேண்டும்.`]},{heading:`7. பயன்பாட்டு நோக்கங்களும் சட்டத் தேவைகளும்`,paragraphs:[`ஒலிபரப்பை இயக்குதல், சேமித்த விருப்பங்களைப் பயன்படுத்துதல், நிலையங்களைக் கண்டறிதல், செயலியை வழக்கம்போல் இயக்குதல் ஆகியவற்றிற்குச் செயல்பாட்டுத் தகவல்கள் பயன்படுகின்றன. இணையச் சேவைகளை வழங்கவும் பாதுகாக்கவும் உள்கட்டமைப்பு வழங்குநர்கள் செயலாக்கும் சில தகவல்களும் தேவைப்படலாம்.`,`தனிப்பட்ட தகவல்களைச் செயலாக்குவதற்கு பொருந்தும் சட்டம் ஒப்புதல், சட்டப்பூர்வ அடிப்படை அல்லது குறிப்பிட்ட அறிவிப்பு தேவைப்படுத்தினால், இந்தக் கொள்கைக்கு மேலாக அந்தச் சட்டத் தேவைகளும் பொருந்தும். சட்டத்தால் வழங்கப்பட்ட தனியுரிமை உரிமைகளை விட்டுக்கொடுக்கச் செய்வது இவ்வாவணத்தின் நோக்கம் அல்ல.`]},{heading:`8. தகவல்களை வைத்திருத்தலும் கட்டுப்படுத்துதலும்`,paragraphs:[`உங்கள் தளத்திற்கோ செயலிக்கோ உரிய தரவை அழிப்பதன் மூலம், பொதுவாகச் சாதனத்தில் சேமித்த RadioBee விருப்பங்களையும் தற்காலிக நிலையப் பட்டியல் தகவல்களையும் நீக்கலாம்; இது பயன்படுத்தும் இயங்குதளத்தைப் பொறுத்தது. ஒலிபரப்பாளர்கள், ஒலிபரப்புச் சேவை வழங்குநர்கள் அல்லது பிற சுயாதீன சேவைகள் வைத்திருக்கும் தகவல்களை நீக்குவதையோ தொடர்ந்து வைத்திருப்பதையோ RadioBee கட்டுப்படுத்தாது.`,`தத்தமது அமைப்புகள் மற்றும் பொருந்தும் சட்டப் பொறுப்புகளின்படி Google Forms-மும் படிவ நிர்வாகியும் தொடர்புப் படிவப் பதிவுகளைச் சேமித்து வைத்திருக்கலாம். சமர்ப்பிக்கப்பட்ட Google Forms பதில்களைப் பயனர்கள் நேரடியாக நீக்குவதற்கான வசதியை RadioBee தற்போது வழங்கவில்லை. சமர்ப்பித்த தகவல்கள் தொடர்பான கேள்விகள் அல்லது கோரிக்கைகளுக்குத் தொடர்புகொள்ளும் படிவத்தைப் பயன்படுத்துங்கள்; அதன்மூலம் முக்கியமான ஆவணங்களை அனுப்ப வேண்டாம்.`]},{heading:`9. தகவல் பகிர்வும் சர்வதேச அணுகலும்`,paragraphs:[`அடிப்படை நிலையப் பட்டியல் மற்றும் ஒலிபரப்பு அம்சங்களை வழங்குவதற்காகச் சாதனத்தில் சேமித்த பிடித்த நிலையங்களையோ விருப்பங்களையோ RadioBee விற்க வேண்டியதில்லை. நீங்கள் தேர்ந்தெடுக்கும் ஒலிபரப்பு மற்றும் சேவை வழங்குநர்களுடன் உங்கள் சாதனம் இணைய வேண்டும்; அவர்கள் வேறு பகுதிகளிலோ நாடுகளிலோ இயங்கலாம். அவர்கள் தகவல்களைக் கையாள்வது அவர்களது நடைமுறைகளுக்கும் பொருந்தும் சட்டங்களுக்கும் உட்பட்டது.`]},{heading:`10. பாதுகாப்பும் வரம்புகளும்`,paragraphs:[`தன் கட்டுப்பாட்டிற்குள் உள்ள தொழில்நுட்பப் பாதுகாப்பு நடவடிக்கைகளை நியாயமான அளவில் மேற்கொள்ள RadioBee முயல்கிறது. ஆனால் எந்த மென்பொருளும் சாதனமும் இணைய இணைப்பும் சேமிப்பகமும் முழுமையான பாதுகாப்புடனோ இடையறாத கிடைப்புடனோ இருக்கும் என்று உத்தரவாதம் அளிக்க முடியாது. உங்கள் இயங்குதளத்தையும் உலாவியையும் புதுப்பித்த நிலையில் வைத்திருந்து, சாதன அனுமதிகளையும் தனியுரிமைக் கட்டுப்பாடுகளையும் பரிசீலிக்கவும்.`]},{heading:`11. குழந்தைகளும் தனியுரிமை உரிமைகளும்`,paragraphs:[`RadioBee பொதுப் பயன்பாட்டிற்கான நிலையப் பட்டியல் சேவையாகும்; குழந்தைகளிடமிருந்து தனிப்பட்ட தகவல்களைக் கேட்டு பெறுவதற்காக வடிவமைக்கப்படவில்லை. தேவையான இடங்களில் மூன்றாம் தரப்பு வானொலிச் சேவைகளை குழந்தைகள் பயன்படுத்துவதைப் பெற்றோரும் பாதுகாவலர்களும் கண்காணிக்க வேண்டும்.`,`உங்கள் இருப்பிடத்தையும் பொருந்தும் சட்டத்தையும் பொறுத்து, தனிப்பட்ட தகவல்கள் குறித்த விவரங்களை அறிதல், அணுகுதல், திருத்துதல், அழிக்கக் கோருதல், குறைகளுக்குத் தீர்வு கோருதல் அல்லது பிற நிவாரணங்களைப் பெறுதல் போன்ற உரிமைகள் உங்களுக்கு இருக்கலாம். சட்டம் கட்டாயப்படுத்தும் தொடர்பு அல்லது குறைதீர் வழிமுறையை, அது கட்டாயமான தகவல்களைச் சேகரிப்பதற்கு முன் சேவை நிர்வாகி வழங்க வேண்டும்.`]},{heading:`12. மாற்றங்களும் தொடர்பும்`,paragraphs:[`செயலியில் மாற்றங்கள் ஏற்பட்டாலோ சட்டத் தேவைகள் வளர்ச்சியடைந்தாலோ இந்தக் கொள்கை புதுப்பிக்கப்படலாம். முக்கிய மாற்றங்கள் திருத்தப்பட்ட நடைமுறைத் தேதியுடன் இப்பக்கத்தில் காட்டப்படும். இக்கொள்கை பற்றிய கேள்விகள் அல்லது கோரிக்கைகளுக்கு RadioBee தொடர்புகொள்ளும் படிவத்தைப் பயன்படுத்தலாம். படிவப் பதிவுகள் Google Forms மூலம் அனுப்பப்படுகின்றன; உலாவியில் சமர்ப்பித்தது மட்டும் அது சென்றடைந்ததையோ பெறப்பட்டதையோ உறுதிப்படுத்தாது.`]}]},terms:{title:`விதிமுறைகளும் நிபந்தனைகளும்`,summary:`மூன்றாம் தரப்பு இணைய வானொலிச் சேவைகளைப் பட்டியலிட்டு இயக்க உதவும் RadioBee-யை அணுகுவதற்கும் பயன்படுத்துவதற்கும் இவ்விதிமுறைகள் பொருந்தும். நடைமுறைக்கு வந்த நாள்: 17 நவம்பர் 2026.`,sections:[{heading:`1. ஏற்பும் சட்டத்திற்கு உட்பட்ட பயன்பாடும்`,paragraphs:[`RadioBee-யை அணுகுவதன் மூலமோ பயன்படுத்துவதன் மூலமோ இவ்விதிமுறைகளையும் பொருந்தும் சட்டங்களையும் பின்பற்ற ஒப்புக்கொள்கிறீர்கள். ஒப்புக்கொள்ளாவிட்டால் சேவையைப் பயன்படுத்த வேண்டாம். உங்கள் அதிகார வரம்பில் சட்டப்படி கட்டுப்படுத்த முடியாத உரிமைகளுடன் ஏதேனும் விதிமுறை முரண்பட்டால், அந்தக் கட்டாய உரிமைகளே மேலோங்கும்.`,`தேவையான அனுமதிகளும் சட்ட உரிமைகளும் உங்களிடம் இருந்தால் மட்டுமே செயலி, ஒலிபரப்பாளர்களின் இணையதளங்கள், ஒலிபரப்புகள் மற்றும் தொடர்புடைய உள்ளடக்கத்தைப் பயன்படுத்த வேண்டும்.`]},{heading:`2. RadioBee வழங்குவது என்ன`,paragraphs:[`இணைய வானொலி நிலையங்களைக் கண்டறிந்து கேட்க RadioBee உதவுகிறது. நிலையப் பட்டியல்கள், சின்னங்கள், விளக்கங்கள், ஒலிபரப்பு இணைப்புகள் ஆகியவை பொதுவில் அணுகக்கூடிய ஆதாரங்களிலிருந்தோ மூன்றாம் தரப்பு வழங்குநர்களிடமிருந்தோ பெறப்பட்டிருக்கலாம். ஒரு நிலையம் பட்டியலில் இருப்பது அதன் உரிமை, கூட்டாண்மை, தொடர்பு, உரிமம் அல்லது ஆதரவை RadioBee பெற்றிருப்பதாகப் பொருளல்ல.`,`நிலைய இணைப்புகள் மூலம் கிடைக்கும் மூன்றாம் தரப்பு நிகழ்ச்சிகளின் ஒலிபரப்பாளர், தயாரிப்பாளர், வெளியீட்டாளர் அல்லது உரிமையாளர் RadioBee அல்ல. ஒலிபரப்பு கிடைப்பதும் அணுகும் நிபந்தனைகளும் சுயாதீன வழங்குநர்களால் தீர்மானிக்கப்படுகின்றன.`]},{heading:`3. ஒலிபரப்புகளும் மூன்றாம் தரப்பு உள்ளடக்கமும் குறித்த உரிமைகள்`,paragraphs:[`மூன்றாம் தரப்பு வானொலி ஒலிபரப்பு, ஒலி, இசை, நிகழ்ச்சி, பரிமாற்றம், நிலைய வணிகச்சின்னம் அல்லது ஒலிபரப்பாளர் சின்னம் ஆகிய எதற்கும் RadioBee உரிமை கோருவதில்லை. அவற்றின் உரிமைகள் சம்பந்தப்பட்ட உரிமையாளர்களிடமும் உரிமம் வழங்குபவர்களிடமும் தொடர்கின்றன.`,`RadioBee பெயர், அசல் இடைமுகம், அசல் ஆவணங்கள் மற்றும் செயலியின் பிற அசல் பொருட்கள் தனியாக உரிமைப் பாதுகாப்பைப் பெற்றிருக்கலாம். இந்த விதிமுறைகள் செயலிக்கோ மூன்றாம் தரப்பு உள்ளடக்கத்திற்கோ உரிமைகளை மாற்றித் தருவதில்லை.`]},{heading:`4. ஒலிபரப்பு இணைப்புகளும் ஒலிபரப்பாளரின் கட்டுப்பாடும்`,paragraphs:[`நிலையங்களும் ஒலிபரப்புச் சேவை வழங்குநர்களும் அறிவிப்பின்றி தங்கள் சேவையை மாற்றலாம், பகுதி வாரியாகக் கட்டுப்படுத்தலாம், இடைநிறுத்தலாம், நிறுத்தலாம், வருவாய் ஈட்டலாம் அல்லது அணுகலைத் தடுக்கலாம். நிலையப் பதிவோ ஒலிபரப்பு இணைப்போ எந்த நேரத்திலும் தவறானதாகவோ அணுக முடியாததாகவோ தடை செய்யப்பட்டதாகவோ பழையதாகவோ மாறலாம்.`,`நிலையப் பெயர், தொடர்புடைய தரவுகள், மொழி, உரிம நிலை, ஒலிபரப்புத் தரம், சிக்னலின் தொடர்ச்சி, நிகழ்ச்சிகளின் கருத்துசார் உள்ளடக்கம் அல்லது சேவை தொடர்ந்து கிடைப்பது குறித்து RadioBee உத்தரவாதம் அளிப்பதில்லை.`]},{heading:`5. மூன்றாம் தரப்பு ஒலிபரப்புகளைப் பயன்படுத்துதல்`,paragraphs:[`பொதுவில் அணுகக்கூடிய ஒலிபரப்பை கேட்க முடிவது மட்டுமே அதன் உள்ளடக்கத்தை நகலெடுக்க, மீண்டும் ஒலிபரப்ப, மறுபகிர்வு செய்ய, பொதுமக்களுக்காக நிகழ்த்த அல்லது வணிகரீதியாகப் பயன்படுத்த உரிமை அளிப்பதில்லை. வழக்கமான அனுமதிக்கப்பட்ட கேட்பதைக் கடந்த பயன்பாட்டிற்கு தேவையான அனுமதிகளைப் பெறுவது உங்கள் பொறுப்பு.`,`பாதுகாப்புக் கட்டுப்பாடுகளை மீறவோ அணுகல் தடைகளைத் தவிர்க்கவோ மூன்றாம் தரப்பு உரிமைகளை மீறவோ அனுமதியின்றி ஒலிபரப்புகளை மறுபகிர்வு செய்யவோ RadioBee-யைப் பயன்படுத்த வேண்டாம். செல்லுபடியாகும் உரிமைக் குறையோ சட்டக் கட்டுப்பாடோ கண்டறியப்பட்டால் RadioBee நிலையப் பதிவை நீக்கலாம் அல்லது கட்டுப்படுத்தலாம்.`]},{heading:`6. உங்கள் பொறுப்புகள்`,points:[`சட்டங்கள், ஒலிபரப்பாளர்களின் நிபந்தனைகள், உரிமங்கள், பிறரது உரிமைகள் மற்றும் நீங்கள் பயன்படுத்தும் தளத்தின் விதிகளைப் பின்பற்றவும்.`,`பதிப்புரிமை அல்லது வணிகச்சின்ன உரிமைகளை மீறவோ பாதுகாப்புக் கட்டுப்பாடுகளைத் தாண்டவோ தீங்கிழைக்கும் மென்பொருளைப் பரப்பவோ பிற பயனர்கள் அல்லது வழங்குநர்களுக்குத் தொந்தரவு செய்யவோ சேவையைப் பயன்படுத்த வேண்டாம்.`,`ஒலிபரப்புகளின் அல்லது நிலையங்களின் உரிமை குறித்து தவறாகக் கூற வேண்டாம்; புகார் வழியாக மற்றொருவரின் தனிப்பட்ட தகவல்களை வெளியிட வேண்டாம்.`,`உங்கள் சாதனங்களையும் கணக்குகளையும் பாதுகாத்து, வெளிப்புற இணைப்புகள் அல்லது சேவைகளைத் திறப்பதற்கு முன் அனுமதிகளைச் சரிபார்க்கவும்.`]},{heading:`7. மூன்றாம் தரப்பு இணையதளங்களும் சேவைகளும்`,paragraphs:[`வசதிக்காக வெளிப்புற இணைப்புகளும் ஒலிபரப்புகளும் வழங்கப்படுகின்றன. தனித்த இணையதளங்கள், ஒலிபரப்பாளர்கள், விளம்பரதாரர்கள், சேவை வழங்குநர்கள் அல்லது பிற மூன்றாம் தரப்பினரை RadioBee மேற்பார்வையிடவோ இயக்கவோ உத்தரவாதம் அளிக்கவோ கட்டுப்படுத்தவோ செய்வதில்லை. அவர்களுடனான உங்கள் தொடர்புகள் அவர்களது விதிமுறைகளுக்கும் கொள்கைகளுக்கும் உட்பட்டவை.`]},{heading:`8. கருத்துகளுக்கு ஆதரவு அளிப்பதாகப் பொருளல்ல`,paragraphs:[`நிலையப் பதிவுகள் தகவலுக்காக மட்டுமே; எந்த ஒலிபரப்பாளர், கருத்து, விளம்பரம், அரசியல் நிலைப்பாடு, மருத்துவ ஆலோசனை, நிதி ஆலோசனை அல்லது பிற ஒலிபரப்பு உள்ளடக்கத்திற்கும் RadioBee ஆதரவு அளிப்பதாகப் பொருளல்ல. பொருந்தும் சட்டம் விதிக்கும் அளவிற்குத் தங்கள் ஒலிபரப்புகளுக்கும் நிகழ்ச்சித் தொகுப்புத் தீர்மானங்களுக்கும் ஒலிபரப்பாளர்களே பொறுப்பாளர்கள்.`]},{heading:`9. தகவல் துல்லியமும் சேவை கிடைப்பதும்`,paragraphs:[`சேவை கிடைக்கும் நிலையில் வழங்கப்படுகிறது. பொருந்தும் சட்டம் அனுமதிக்கும் முழு அளவிற்கு, இடையறாத அணுகல், பிழையற்ற செயல்பாடு, குறிப்பிட்ட நோக்கத்திற்கான பொருத்தம், மூன்றாம் தரப்பு ஒலிபரப்புகள் உரிமை மீறாதிருப்பது, நிலையத் தகவல்களின் துல்லியம் அல்லது முழுமை ஆகியவை தொடர்பான உத்தரவாதங்களை RadioBee மறுக்கிறது.`,`பாதுகாப்பு, தொழில்நுட்பச் செயல்பாடு, உரிமைகளைக் காக்கும் தேவைகள் அல்லது பிற நியாயமான காரணங்களுக்காக ஒரு நிலையப் பதிவு, இணைப்பு, அம்சம் அல்லது சேவையை RadioBee மாற்றவோ இடைநிறுத்தவோ நீக்கவோ நிறுத்தவோ செய்யலாம்.`]},{heading:`10. பொறுப்பின் வரம்புகள்`,paragraphs:[`பொருந்தும் சட்டம் அனுமதிக்கும் அதிகபட்ச அளவிற்கு, மூன்றாம் தரப்பு ஒலிபரப்புகள், சேவை இடையூறுகள், சாதனப் பொருந்தாமை, கிடைக்காத ஒலிபரப்புகள், உள்ளூர் தரவு இழப்பு அல்லது உங்கள் சேவைப் பயன்பாடு ஆகியவற்றால் ஏற்படும் மறைமுக, தற்செயலான, சிறப்பான, தொடர்விளைவான அல்லது முன்மாதிரித் தண்டனை சார்ந்த இழப்புகளுக்கு RadioBee-யும் அதன் நிர்வாகிகளும் பொறுப்பல்ல.`,`பொருந்தும் சட்டத்தால் நீக்கவோ குறைக்கவோ முடியாத பொறுப்புகள், குறிப்பாகத் தவிர்க்க முடியாத சட்டப் பொறுப்புகள், இந்த விதியால் நீக்கப்படுவதில்லை அல்லது குறைக்கப்படுவதில்லை. சட்டப்படி வழங்கப்படும் நுகர்வோர், தனியுரிமை, அறிவுசார் சொத்து அல்லது பிற கட்டாய உரிமைகளை இவ்விதிமுறைகள் நீக்குவதில்லை.`]},{heading:`11. உங்கள் தவறான பயன்பாட்டிற்கான பொறுப்பு`,paragraphs:[`உங்கள் சட்டவிரோதப் பயன்பாடு, அனுமதியற்ற மறுபகிர்வு மற்றும் பிறரது உரிமை மீறல்களுக்கு நீங்களே பொறுப்பு. பொருந்தும் சட்டம் அனுமதிக்கும் இடங்களில், நீங்கள் அறிந்தே செய்யும் தவறான பயன்பாடோ இவ்விதிமுறைகளின் முக்கிய மீறலோ காரணமாக எழும் மூன்றாம் தரப்புக் கோரிக்கைகளை, RadioBee-யின் சொந்த சட்டவிரோதச் செயலால் ஏற்பட்ட அளவைத் தவிர்த்து, எதிர்கொள்ள நீங்கள் ஒப்புக்கொள்கிறீர்கள்.`]},{heading:`12. அறிவுசார் சொத்து புகார்களும் நீக்கமும்`,paragraphs:[`அறிவுசார் சொத்து மற்றும் ஒலிபரப்பாளர்களின் உரிமைகளை RadioBee மதிக்கிறது. சரிபார்க்கப்பட்ட உரிமையாளர்கள், அவர்களால் அங்கீகரிக்கப்பட்ட பிரதிநிதிகள் மற்றும் ஆதாரப்பூர்வமான கவலைகளுள்ள பயனர்கள் குறிப்பிட்ட நிலையப் பதிவு, ஒலிபரப்பு URL, சின்னம் அல்லது பிற பொருள் குறித்து பதிப்புரிமை மற்றும் நீக்கக் கொள்கையில் விவரிக்கப்பட்ட முறையில் புகார் அளிக்கலாம்.`,`நம்பத்தகுந்த உரிமைக் கோரிக்கை, செல்லுபடியாகும் சட்ட ஆணை, ஆதாரப்பூர்வ உரிமை மீறல் குறை அல்லது பிற நியாயமான காரணம் இருந்தால் RadioBee சர்ச்சைக்குரிய பதிவை விசாரித்து நீக்கலாம் அல்லது செயலிழக்கச் செய்யலாம். பட்டியலிலிருந்து நீக்குவதால் மூன்றாம் தரப்புச் சேவையகங்கள் கட்டுப்படுத்தும் பிரதிகளையோ ஒலிபரப்புகளையோ நீக்க முடியாது.`]},{heading:`13. இடையறாத சேவையை நம்பிச் சார்ந்திருக்க வேண்டாம்`,paragraphs:[`RadioBee அவசரநிலை, பொது பாதுகாப்பு அல்லது உறுதியாகத் தகவல் வழங்கும் சேவை அல்ல. அவசர எச்சரிக்கைகள் அல்லது நேரம் முக்கியமான அறிவுறுத்தல்களுக்கு இணைய வானொலியை மட்டுமே நம்பியிருக்க வேண்டாம்.`]},{heading:`14. பொருந்தும் சட்டமும் தகராறுகளும்`,paragraphs:[`சேவையின் பயன்பாடு குறிப்பிட்ட செயல், இடம் மற்றும் சம்பந்தப்பட்ட தரப்பினருக்கு பொருந்தும் சட்டங்களுக்கு உட்பட்டது. தகராறு தீர்வும் நீதிமன்ற அதிகார வரம்பும் தொடர்பான எந்தத் தேவைகளும் கட்டாயச் சட்டங்களுக்கும் பொருந்தும் நுகர்வோர் பாதுகாப்பிற்கும் உட்பட்டவை. இவ்விதிமுறைகள் எந்த ஒரு நீதிமன்றத்தையும் மட்டும் நிர்ணயிக்கவோ விட்டுக்கொடுக்க முடியாத சட்ட நிவாரணங்களை நீக்கவோ செய்வதில்லை.`]},{heading:`15. மாற்றங்கள், விதிகளின் தனித்த செல்லுபடித்தன்மை மற்றும் தொடர்பு`,paragraphs:[`அம்சங்கள், வெளிப்புறச் சேவைகள், சட்டத் தேவைகள் மாறும்போது RadioBee இவ்விதிமுறைகளைத் திருத்தலாம். இப்பக்கத்தின் தேதி நடைமுறையில் உள்ள பதிப்பைக் குறிக்கிறது. ஒரு விதி செல்லாது என்று தீர்மானிக்கப்பட்டாலும் சட்டப்படி இயலும் அளவிற்கு மற்ற விதிகள் தொடர்ந்து செல்லுபடியாகும்.`,`கேள்விகளுக்கும் திருத்தங்களுக்கும் தொடர்புகொள்ளும் படிவத்தைப் பயன்படுத்துங்கள். உலாவி Google Forms-க்கு கோரிக்கை அனுப்பும்போது Google வழங்கும் தனிப்பட்ட பெறுதல் உறுதிப்படுத்தலைப் பெற முடியாததால், திரையில் சமர்ப்பிப்பு வெற்றிச் செய்தி தோன்றுவது உலாவியின் கோரிக்கை முடிந்ததையே குறிக்கும்; தகவல் RadioBee நிர்வாகியிடம் சென்றடைந்ததையோ அவர் படித்ததையோ உறுதி செய்யாது.`]}]},"copyright-policy":{title:`பதிப்புரிமை மற்றும் நீக்கக் கொள்கை`,summary:`ஒலிபரப்புகள், இசை, நிகழ்ச்சிகள், வணிகச்சின்னங்கள் மற்றும் மூன்றாம் தரப்பினரின் பிற உரிமைகளை RadioBee மதிக்கிறது. ஆதாரப்பூர்வ புகார்களை ஆய்வு செய்து, தேவையானபோது நிலையப் பதிவுகளை நீக்குவோம் அல்லது முடக்குவோம். நடைமுறைக்கு வந்த நாள்: 17 நவம்பர் 2026.`,sections:[{heading:`1. மூன்றாம் தரப்பு ஒலிபரப்புகளில் உரிமை கோராமை`,paragraphs:[`RadioBee ஒரு சுயாதீன நிலையக் கண்டறிதல் மற்றும் ஒலிபரப்பு இயக்கும் செயலியாகும். மூன்றாம் தரப்பு வானொலி ஒலிபரப்புகள், இசை, நிகழ்ச்சிகள், பரிமாற்றங்கள், நிலையப் பெயர்கள் அல்லது சின்னங்களை RadioBee சொந்தமாகக் கொண்டிருக்கவோ தயாரிக்கவோ ஒலிபரப்பாளர்கள் சார்பில் உரிமம் வழங்கவோ அவற்றில் உரிமை கோரவோ செய்வதில்லை. அந்த உரிமைகள் ஒலிபரப்பாளர்கள், பதிப்புரிமையாளர்கள் மற்றும் தொடர்புடைய உரிமம் வழங்குபவர்களிடமே உள்ளன.`,`ஒரு நிலையம் RadioBee பட்டியலில் இடம்பெறுவது, அந்த ஒலிபரப்பாளர் செயலிக்கு நிதியுதவி அளித்துள்ளார், ஆதரவு தெரிவித்துள்ளார், உரிமம் அளித்துள்ளார் அல்லது அனுமதி வழங்கியுள்ளார் என்று பொருளல்ல.`]},{heading:`2. நீக்கமும் திருத்தமும் குறித்த எங்கள் அணுகுமுறை`,paragraphs:[`அனுமதியற்ற பதிவுகள், உரிமை முரண்பாடுகள், தவறான உரிமைக் குறிப்புகள், தடைசெய்யப்பட்ட அணுகல் அல்லது பிற நியாயமான குறைகள் குறித்து தெளிவாக அடையாளம் காணப்பட்ட, நல்லெண்ணத்துடன் சமர்ப்பிக்கப்பட்ட புகார்களை ஆய்வு செய்ய முயல்கிறோம். நம்பத்தகுந்த சான்றுகளோ செல்லுபடியாகும் சட்ட அடிப்படையோ நடவடிக்கையை நியாயப்படுத்தினால் நிலையப் பதிவு, சின்னம், விளக்கம், ஒலிபரப்பு இணைப்பு அல்லது அம்சத்தை RadioBee விரைவாக நீக்கவோ முடக்கவோ திருத்தவோ செய்யலாம்.`,`புகார் ஆய்வில் இருக்கும் காலத்தில் அணுகலைத் தற்காலிகமாகக் கட்டுப்படுத்தவும் RadioBee முடிவு செய்யலாம். கிடைக்கும் தகவல்களையும் பொருந்தும் சட்டத்தையும் கருத்தில் கொண்டு தீர்மானங்கள் எடுக்கப்படும்; புகார் அளிப்பது குறிப்பிட்ட முடிவு கிடைக்கும் என்பதற்கான உத்தரவாதமல்ல.`]},{heading:`3. புகாரில் சேர்க்க வேண்டிய தகவல்கள்`,points:[`நிலையத்தின் பெயர், RadioBee-யில் உள்ள அதன் துல்லியமான பட்டியல் URL, தெரிந்தால் தொடர்புடைய ஒலிபரப்பு அல்லது பட URL.`,`சர்ச்சைக்குரிய படைப்பு, வணிகச்சின்னம், ஒலிபரப்பு அல்லது உரிமை என்ன என்பது மற்றும் குறையின் தெளிவான விளக்கம்.`,`உங்களுக்குள்ள உரிமையையோ அதன் சார்பில் செயல்படும் அதிகாரத்தையோ உறுதிப்படுத்தும் சட்ட அல்லது உண்மை அடிப்படை மற்றும் ரகசியமல்லாத ஆதாரங்கள்.`,`நீங்கள் கோரும் துல்லியமான நடவடிக்கை: திருத்தம், நீக்கம், ஒலிபரப்பை முடக்குதல் அல்லது பொருத்தமான வேறு தீர்வு.`,`தொடர்புகொள்வதற்கான மின்னஞ்சல் முகவரி; முக்கிய ஆதாரங்களை அனுப்ப வேண்டுமாயின் மாற்று பாதுகாப்பான தொடர்பு வழிக்கான கோரிக்கை.`]},{heading:`4. புகார் தெரிவிக்கும் வழி`,paragraphs:[`குறையைத் தெரிவிக்கவும், குறிப்பிட்ட நிலையப் பதிவை அடையாளம் காட்டவும், கோரும் தீர்வை விவரிக்கவும் RadioBee தொடர்புகொள்ளும் படிவத்தைப் பயன்படுத்துங்கள். படிவத் தகவல்கள் திட்ட நிர்வாகி அணுகுவதற்காக Google Forms-க்கு அனுப்பப்படுகின்றன; இது ரகசியச் சட்ட அறிவிப்புகளுக்கான தளமோ பெறுதல் உறுதிப்படுத்தப்பட்ட அமைப்போ அல்ல.`,`அடையாள ஆவணங்கள், முகவரிகள், தனிப்பட்ட ஒப்பந்தங்கள், வெளியிடப்படாத படைப்புகள், உள்நுழைவு விவரங்கள் அல்லது முக்கிய ஆதாரங்களை இந்தப் படிவத்தில் சமர்ப்பிக்க வேண்டாம். அவை தேவைப்பட்டால் முதலில் பொருத்தமான பாதுகாப்பான வழியைக் கோருங்கள்.`]},{heading:`5. ஆய்வும் நடவடிக்கையும்`,paragraphs:[`கிடைக்கும் புகார் வழி மூலம் தகவல் வந்தால், திட்டம் நிலைய URL, மூலத் தகவல்கள், கிடைக்கும் உரிமை விவரங்கள், ஒலிபரப்பாளர் விதித்த கட்டுப்பாடுகள் மற்றும் கோரப்பட்ட தீர்வு ஆகியவற்றைச் சரிபார்க்கலாம். புகார் முழுமையற்றதாகவோ சர்ச்சைக்குரியதாகவோ இருந்தால் கூடுதல் விளக்கம் கேட்கப்படலாம்.`,`நியாயமான ஆதாரமுள்ள குறைகள் பட்டியலை நீக்குதல், ஒலிபரப்புக்கான அணுகலைக் கட்டுப்படுத்துதல் அல்லது உரிமைக் குறிப்புகளைத் திருத்துதல் போன்ற நடவடிக்கைகளுக்கு வழிவகுக்கலாம். ஒலிபரப்பாளரோ சேவை வழங்குநரோ இயக்கும் உள்கட்டமைப்பில் உள்ள அசல் ஒலிபரப்பை RadioBee நீக்கவோ கட்டுப்படுத்தவோ முடியாது. பொருந்தும் விதிகளின்படி முறையான சட்ட அறிவிப்புகளும் நீதிமன்ற ஆணைகளும் கையாளப்படும்.`]},{heading:`6. ஒலிபரப்பாளரின் ஒப்புதலும் பயன்பாட்டுக் கட்டுப்பாடுகளும்`,paragraphs:[`ஒலிபரப்பு பொதுவில் அணுகக்கூடியதாக இருப்பது மட்டுமே அதை மறுபகிர்வு செய்ய, மீண்டும் ஒலிபரப்ப, வணிகரீதியாகப் பயன்படுத்த அல்லது நிலையச் சின்னத்தைப் பயன்படுத்த அனுமதி அளிப்பதில்லை. பயனர்கள் பொருந்தும் உரிமைகள், ஒலிபரப்பாளரின் நிபந்தனைகள் மற்றும் தங்கள் செயல்களுக்குத் தேவையான அனுமதிகளை மதிக்க வேண்டும்.`]},{heading:`7. நல்லெண்ணப் புகார்களும் முரண்படும் உரிமைகளும்`,paragraphs:[`துல்லியமான தகவல்களைச் சமர்ப்பிக்கவும்; உரிமையாளராகத் தெரிந்தே ஆள்மாறாட்டம் செய்யவோ பொய்யான தகவல்களை அளிக்கவோ வேண்டாம். நிலைய நிர்வாகியோ பாதிக்கப்பட்ட பிற தரப்பினரோ பொருத்தமான புகார் வழி மூலம் திருத்தங்களையோ அனுமதி ஆதாரங்களையோ சமர்ப்பிக்கலாம்.`,`நடவடிக்கையை முடிவு செய்வதற்கு முன் உரிமையாளர் நிலை, உரிமங்கள், சட்ட விலக்குகள், அனுமதிகள், ஒலிபரப்பாளரின் அறிவுறுத்தல்கள் மற்றும் சர்ச்சைக்குரிய பதிவின் சூழ்நிலை ஆகியவற்றை RadioBee பரிசீலிக்கலாம். சட்டப்படி பொருந்தாத வரை இங்கு முறையான சட்டப் பதில் அறிவிப்பு அல்லது தகராறு தீர்வு நடைமுறை இருப்பதாகப் பொருள் கொள்ளக் கூடாது.`]},{heading:`8. வணிகச்சின்னங்களும் நிலைய அடையாளங்களும்`,paragraphs:[`மூன்றாம் தரப்பு நிலையப் பெயர்கள், வணிகச்சின்னங்கள், படங்கள் ஆகியவை தொடர்புடைய சேவைகளை அடையாளம் காட்டுவதற்காக மட்டுமே பயன்படுத்தப்படுகின்றன. அவை இடம்பெறுவது நிதியுதவி, ஆதரவு அல்லது உரிமை மாற்றத்தைச் சுட்டுவதில்லை. தவறான சின்னப் பயன்பாடு அல்லது அனுமதியற்ற படங்கள் குறித்து உரிமையாளர்கள் ஆய்வுக்காகப் புகார் அளிக்கலாம்.`]},{heading:`9. மீண்டும் ஏற்படும் குறைகளும் புதுப்பிப்புகளும்`,paragraphs:[`ஒரே ஆதாரத்தைச் சார்ந்த குறைகள் மீண்டும் ஏற்பட்டால் RadioBee தொடர்புடைய பதிவுகள் அல்லது அம்சங்களைத் தேவைக்கேற்ப தடுக்கலாம் அல்லது நீக்கலாம். தொடர்புப் படிவச் சமர்ப்பிப்பு, உரிமை சரிபார்ப்பு அல்லது சட்டப் பொறுப்புகளில் மாற்றங்கள் ஏற்பட்டால் இக்கொள்கை புதுப்பிக்கப்படலாம். சட்டப்படி கட்டாயமான குறைதீர் அல்லது அறிவிப்பு நடைமுறைகள் இப்பொதுவான விளக்கத்தைவிட முன்னுரிமை பெறும்.`]}]},contact:{title:`தொடர்புகொள்ளுங்கள்`,summary:`கேள்விகள், நிலையத் தகவல் திருத்தங்கள், ஒலிபரப்பாளர் உரிமைகள் குறித்த கவலைகள் அல்லது ஆலோசனைகள் உள்ளனவா? RadioBee தொடர்புப் படிவத்தைத் திறக்க கீழே பொருத்தமான தலைப்பைத் தேர்ந்தெடுக்கவும்.`,sections:[{heading:`RadioBee-யைத் தொடர்புகொள்ளுதல்`,paragraphs:[`உங்கள் பெயர், மின்னஞ்சல் முகவரி மற்றும் தொடர்புகொள்வதன் நோக்கத்தை வழங்கவும். நிலைய விவரங்களை விருப்பப்பட்டால் சேர்க்கலாம். படிவத்தைச் சமர்ப்பிப்பதன் மூலம் உங்கள் தகவல்கள் செயலாக்கத்திற்காகவும் RadioBee படிவ நிர்வாகி அணுகுவதற்காகவும் Google Forms-க்கு அனுப்பப்படும்.`,`சமர்ப்பித்ததனால் பதில் கிடைப்பது உறுதியாகாது; இது சரிபார்க்கப்பட்ட சட்ட அறிவிப்பு வழியையும் உருவாக்காது. ரகசிய ஆவணங்கள், கடவுச்சொற்கள் அல்லது முக்கியமான தனிப்பட்ட தகவல்களைச் சேர்க்க வேண்டாம்.`]}]}};var c={privacy:{heading:`13. சோதனை ஒலிப்பதிவும் சாதனத்தில் சேமிக்கப்படும் ஒலியும்`,paragraphs:[`விருப்பத்தேர்வான சோதனை ஒலிப்பதிவு வசதி இயக்கப்பட்டிருந்தால், ஒலி பயனரின் சாதனத்தில் பதிவு செய்யப்பட்டு, பயனர் தேர்ந்தெடுக்கும் சேமிப்பிடத்தில் கோப்பாகச் சேமிக்கப்படலாம் அல்லது ஏற்றுமதி செய்யப்படலாம். RadioBee இந்தப் பதிவுகளைத் தனது சேவையகங்களில் பதிவேற்றவோ சேமித்து வழங்கவோ செய்வதில்லை. சேமித்த கோப்புகளைப் பயனரே கட்டுப்படுத்துகிறார்; சாதனக் காப்புப் பிரதிச் சேவைகள், சேமிப்பக வழங்குநர்கள், பகிரப் பயன்படுத்தப்படும் செயலிகள் தங்கள் விதிகளின்படி அவற்றின் பிரதிகளைச் செயலாக்கலாம்.`,`பதிவுகளில் பதிப்புரிமை கொண்ட ஒலிபரப்புகளோ நிகழ்ச்சிகளில் இடம்பெறும் தனிப்பட்ட தகவல்களோ இருக்கலாம். பதிவை சட்டப்படி உருவாக்குதல், வைத்திருத்தல், பாதுகாத்தல், அழித்தல், பின்னர் பகிர்தல் அல்லது பயன்படுத்துதல் ஆகியவற்றிற்குப் பதிவு செய்பவரே பொறுப்பு.`]},terms:{heading:`16. சோதனை ஒலிப்பதிவு வசதியும் பயனரின் பொறுப்பும்`,paragraphs:[`விருப்பத்தேர்வான ஒலிப்பதிவு வசதி என்பது சாதனத்தில் ஒலியைப் பதிவு செய்தல், சேமித்தல், வேறு வடிவத்திற்கு மாற்றுதல் மற்றும் சாதனப் பொருந்துதலைச் சோதிப்பதற்கான சோதனை அம்சமாகும். இது உரிமம் பெற்ற ஒலிப்பதிவுச் சேவை அல்ல; இடையறாத பதிவு அல்லது கோப்பை மீட்டெடுப்பதற்கான உத்தரவாதமுமல்ல; மூன்றாம் தரப்பு ஒலிபரப்பை பதிவு செய்ய அனுமதியும் அல்ல.`,`பதிவு செய்யத் தேர்ந்தெடுக்கும் நபரே பதிவைத் தொடங்குதல், எதைச் சேமிக்கவோ பகிரவோ வேண்டும் என்று தீர்மானித்தல், ஒலிபரப்பாளர்கள் அல்லது பிற உரிமையாளர்களிடமிருந்து தேவையான அனுமதிகளைப் பெறுதல், பதிப்புரிமை, தனியுரிமை, ஒலிபரப்பாளர் நிபந்தனைகள் மற்றும் பொருந்தும் சட்டங்களைப் பின்பற்றுதல் ஆகிய அனைத்திற்கும் முழுப் பொறுப்பாளர். பதிவு செய்தல், நகலெடுத்தல், பகிர்தல் அல்லது பிற பயன்பாடுகள் தடை செய்யப்பட்ட இடங்களில் அவற்றைச் செய்ய வேண்டாம்.`,`பயனர்கள் உருவாக்கும் பதிவுகளை RadioBee, அதன் உரிமையாளர், உருவாக்குநர்கள், பங்களிப்பாளர்கள் அல்லது நிர்வாகிகள் தொடங்கவோ வழிநடத்தவோ மேற்பார்வையிடவோ தங்கள் சேவையகங்களில் வைத்திருக்கவோ விநியோகிக்கவோ செய்வதில்லை. பொருந்தும் சட்டம் அனுமதிக்கும் அதிகபட்ச அளவிற்கு, பயனர் உருவாக்கிய, வைத்திருந்த, பகிர்ந்த அல்லது தவறாகப் பயன்படுத்திய பதிவுகள் மற்றும் அந்தப் பயனரின் செயலால் எழும் கோரிக்கைகளுக்கான பொறுப்பையும் சட்டப் பொறுப்பேற்பையும் அவர்கள் மறுக்கின்றனர். சட்டப்படி நீக்கவோ குறைக்கவோ முடியாத பொறுப்புகளை இந்த அறிவிப்பு நீக்குவதில்லை.`]},"copyright-policy":{heading:`10. பயனர் தொடங்கும் சோதனை ஒலிப்பதிவுகள்`,paragraphs:[`சாதனத்தில் ஒலியைப் பதிவு செய்து ஏற்றுமதி செய்வதைச் சோதிப்பதற்காக விருப்பத்தேர்வான பதிவு வசதி வழங்கப்படுகிறது. இந்த வசதி இருப்பது மட்டுமே வானொலி ஒலிபரப்புகளையோ பதிப்புரிமை கொண்ட பிற உள்ளடக்கங்களையோ பதிவு செய்ய, நகலெடுக்க, பகிர, வெளியிட அல்லது வணிகரீதியாகப் பயன்படுத்த எந்த உரிமத்தையோ அனுமதியையோ வழங்குவதில்லை.`,`ஒவ்வொரு பதிவையும் தனிப்பட்ட பயனரே தொடங்கி கட்டுப்படுத்துகிறார். தேவையான அனுமதிகளைப் பெறுவதற்கும் பொருந்தும் உரிமைகள், சட்டங்கள் மற்றும் ஒலிபரப்பாளர் கட்டுப்பாடுகளைப் பின்பற்றுவதற்கும் அவரே முழுப் பொறுப்பாளர். RadioBee, அதன் உரிமையாளர் மற்றும் நிர்வாகிகள் பயனர் பதிவுகளை உருவாக்குபவர்களோ விநியோகிப்பவர்களோ அல்ல; சட்டம் அனுமதிக்கும் அளவிற்கு தனிநபர்களின் அனுமதியற்ற பதிவுகளுக்கும் பயன்பாடுகளுக்கும் அவர்கள் சட்டப் பொறுப்பை ஏற்கவில்லை. கட்டாயச் சட்டப் பொறுப்புகளும் உரிமைகளும் இதனால் பாதிக்கப்படுவதில்லை.`]}};var p={privacy:{title:`गोपनीयतानीतिः`,summary:`RadioBee भवतः उपकरणे किं सञ्चिनोति, तृतीयपक्षीयप्रसारणसेवाभिः काः सूचनाः साझीकर्तुं शक्यन्ते, तासां सेवानां विषये अस्माकं नियन्त्रणस्य सीमाः काः इति एषा नीतिः विवृणोति। प्रभाविदिनाङ्कः — १७ नवम्बर २०२६।`,sections:[{heading:`१. व्याप्तिः सेवा च`,paragraphs:[`RadioBee इत्येषः अन्तर्जालवाणीकेन्द्राणाम् अन्वेषणश्रवणयोः साहाय्यं कुर्वन् अनुप्रयोगः अस्ति। एषा नीतिः RadioBee जालस्थले तथा अनुप्रयोगेन प्रदत्तासु सुविधासु प्रवर्तते। RadioBee द्वारा भवता उपयुज्यमानानां प्रसारकाणां, प्रसारणसेवाप्रदातॄणाम्, परिचालनप्रणालीनाम्, अनुप्रयोगविपणीनां वा अन्येषां जालस्थलानां स्वतन्त्रगोपनीयतासूचनानां व्यवहाराणां वा स्थाने एषा न प्रवर्तते।`,`RadioBee तृतीयपक्षीयध्वनिप्रवाहाणां सूचीं प्रदर्शयति तथा तान् श्रावयति। प्रसारकाः तेषां सेवाप्रदातारश्च स्वकीयसेवकेषु प्राप्तान् जालानुरोधान् तत्सम्बद्धसूचनाश्च कथं संसाधयन्ति इति स्वतन्त्रतया निर्धारयन्ति।`]},{heading:`२. अनुप्रयोगे सञ्चिताः सूचनाः`,paragraphs:[`वर्तमानः अनुप्रयोगः भवतः विकल्पान् कार्यसञ्चालनार्थं आवश्यकदत्तांशांश्च ब्राउजरस्य अथवा उपकरणस्य सञ्चयव्यवस्थायां रक्षति। उपयुज्यमानसुविधानुसारं प्रियवाणीकेन्द्राणि, प्रदर्शनीयभाषा, रूपविन्यासः, मुखपृष्ठकेन्द्रचयनं, अस्थायिरूपेण सञ्चिता केन्द्रसूची इत्यादीनि अत्र समाविष्टानि भवितुम् अर्हन्ति।`,`जालस्थलदत्तांशानां मार्जनात्, ब्राउजरपरिवर्तनात् अथवा अनुप्रयोगस्य निष्कासनात् एते स्थानीयविकल्पाः नष्टाः भवितुम् अर्हन्ति। स्थानीयसञ्चयस्य उपलब्धिः स्थायित्वं च ब्राउजरस्य तथा परिचालनप्रणाल्याः नियन्त्रणाधीनम् अस्ति।`]},{heading:`३. वाणीश्रवणं तृतीयपक्षीयजालानुरोधाश्च`,paragraphs:[`भवान् यदा किञ्चित् वाणीकेन्द्रं श्रावयति तदा भवतः उपकरणं सम्बन्धितप्रसारकेण प्रसारणसेवाप्रदात्रा वा सह जालेन सम्बध्यते। भवतः IP-सङ्केतः, उपकरणब्राउजरविवरणानि, अनुरोधसमयः, ध्वनिप्रवाहस्य URL इत्यादयः जालानुरोधसम्बद्धाः तान्त्रिकविवरणाः तैः प्राप्तुं शक्यन्ते। तेषां दत्तांशसङ्ग्रहः, कुक्की-प्रयोगः, अभिलेखनम्, भौगोलिकप्रतिबन्धाः, दत्तांशधारणप्रथाश्च RadioBee-नियन्त्रणात् बहिः सन्ति।`,`केन्द्रसूची तथा अनुप्रयोगसंसाधनानि GitHub Pages अथवा अन्याभ्यः विन्यस्ताभ्यः संरचनासेवाभ्यः प्राप्तानि भवितुम् अर्हन्ति। तासां सेवाप्रदातारः स्वकीयनीत्यनुसारं तान्त्रिकानुरोधाभिलेखान् संसाधयितुं शक्नुवन्ति।`]},{heading:`४. उपकरणसञ्चयः विकल्पाश्च`,paragraphs:[`RadioBee समर्थितान् भवद्विकल्पान् स्मर्तुं तथा यत्र सम्भवति तत्र वाणीकेन्द्रसूचीं तात्कालिकरूपेण रक्षितुं उपकरणस्य स्थानीयसञ्चयं प्रयुङ्क्ते। अनेन प्रियकेन्द्राणि प्रदर्शनविकल्पाश्च पुनरागमनेऽपि कार्यं कर्तुं शक्नुवन्ति।`,`भवतः विन्यासस्य, सञ्चयसीमायाः, गोपनीयताविधानस्य अथवा अनुरक्षणकार्यस्य कारणात् ब्राउजरः परिचालनप्रणाली वा सञ्चितदत्तांशान् मार्जयितुं शक्नोति। उपकरणे रक्षिताः विकल्पाः अनिश्चितकालं उपलब्धाः भविष्यन्तीति RadioBee प्रत्याभूतिं न ददाति।`]},{heading:`५. भवता स्वेच्छया प्रेषिताः सूचनाः`,paragraphs:[`RadioBee सम्पर्कप्रपत्रं प्रददाति, यत् तृतीयपक्षीयया Google Forms सेवया प्रेष्यते। भवान् तत् प्रेषयति चेत् नाम, विद्युत्पत्रसङ्केतः, ऐच्छिकदूरभाषाङ्कः, प्रश्नस्य प्रयोजनम्, सन्देशः, ऐच्छिककेन्द्रविवरणानि च Google प्रति संसाधनार्थं प्रेष्यन्ते तथा RadioBee प्रपत्रसञ्चालकस्य उपयोगार्थम् उपलब्धानि भवन्ति। एतानि प्रपत्रप्रविष्टीनि RadioBee ब्राउजरविकल्परूपेण न सञ्चीयन्ते।`,`Google स्वकीयशर्तानां गोपनीयताप्रथानां च अनुसारं प्रपत्रप्रविष्टीन् संसाधयति। प्रश्नप्रेषणं तस्मै सम्मतिदानं च स्वैच्छिकम् अस्ति। पृथक् सुरक्षितसम्पर्कमार्गे सहमतिः न जाता चेत् गुप्तशब्दान्, परिचयपत्राणि, संवेदनशीलानुबन्धविवरणानि अन्यानि वा गोपनीयवस्तूनि मा प्रेषयतु।`]},{heading:`६. कुक्की, उपयोगविश्लेषणं विज्ञापनानि च`,paragraphs:[`पूर्वोक्तरीत्या अनुप्रयोगकार्यसञ्चालनार्थं RadioBee उपकरणब्राउजरसञ्चयं प्रयुङ्क्ते। प्रत्येकं तृतीयपक्षीयप्रसारणसेवाप्रदाता, ब्राउजरः, परिचालनप्रणाली वा संरचनाप्रदाता कुक्की, उपयोगविश्लेषणं, विज्ञापनप्रौद्योगिकीम् अथवा अभिलेखान् न प्रयुङ्क्ते इति एषा नीतिः न प्रतिजानाति।`,`यदि भविष्यति काले RadioBee स्वकीयम् उपयोगविश्लेषणम्, विज्ञापनसंयोजनम्, परिचयप्रमाणीकरणं वा सेवकाधारितं नूतनसम्पर्कतन्त्रं योजयेत्, तर्हि तासां सुविधानां तथा विध्यपेक्षितविकल्पानां सूचनानां च वर्णनार्थम् एषा नीतिः पुनरवलोक्य नवीकरणीया।`]},{heading:`७. उपयोगप्रयोजनानि विध्यपेक्षाश्च`,paragraphs:[`ध्वनिश्रवणं, सञ्चितविकल्पानां उपयोगः, वाणीकेन्द्रान्वेषणम्, अनुप्रयोगस्य सामान्यकार्यसञ्चालनं च इत्येतेषां कृते कार्यदत्तांशाः प्रयुज्यन्ते। जालसेवानां प्रदाने संरक्षणे च संरचनाप्रदातृभिः संसाध्यमानाः कतिचन सूचनाः अपि आवश्यकाः भवितुम् अर्हन्ति।`,`यदि प्रयोज्यविधिः वैयक्तिकदत्तांशसंसाधनार्थं सम्मतिं, वैधानिकाधारं वा विशिष्टसूचनां वा अपेक्षते तर्हि एतस्याः नीतेः अतिरिक्तं ताः विध्यपेक्षाः अपि प्रवर्तन्ते। विधिदत्तगोपनीयताधिकाराणां परित्यागः अस्य लेखस्य अभिप्रायः नास्ति।`]},{heading:`८. दत्तांशधारणं नियन्त्रणं च`,paragraphs:[`उपकरणप्रणाल्यनुसारं अनुप्रयोगस्य अथवा ब्राउजरस्य जालस्थलदत्तांशान् मार्जयित्वा भवान् सामान्यतः स्थानीयRadioBee-विकल्पान् तात्कालिककेन्द्रसूचीं च निष्कासयितुं शक्नोति। प्रसारकैः, प्रवाहसेवाप्रदातृभिः अन्यैः स्वतन्त्रसेवाप्रदातृभिश्च धारितानां सूचनानां मार्जनं धारणं वा RadioBee न नियन्त्रयति।`,`Google Forms तथा प्रपत्रसञ्चालकः स्वकीयानुसारव्यवस्थाभिः प्रयोज्यवैधानिककर्तव्यैश्च प्रपत्रप्रविष्टीन् सञ्चिन्वन्ति धारयन्ति च इति सम्भाव्यते। Google Forms द्वारा प्रेषितप्रत्युत्तराणां स्वयमेव मार्जनार्थं उपयोक्तृमुखी सुविधा RadioBee अद्य न प्रददाति। प्रेषितसूचनासम्बद्धप्रश्नानां निवेदनानां च कृते सम्पर्कप्रपत्रं प्रयुङ्क्ताम्; तेन संवेदनशीलानि पत्राणि मा प्रेषयतु।`]},{heading:`९. सूचनासाझाकरणम् अन्तर्राष्ट्रीयोपलब्धिश्च`,paragraphs:[`स्वकीयं केन्द्रसूचीश्रवणसेवां प्रदातुं RadioBee स्थानीयप्रियकेन्द्रविकल्पान् विक्रेतुं न आवश्यकम्। भवतः उपकरणं चितैः प्रसारणसंरचनाप्रदातृभिः सम्बध्यते; ते अन्येषु प्रदेशेषु राष्ट्रेषु वा स्थिताः स्युः। तेषां अनुरोधदत्तांशव्यवहारः तेषां स्वकीयप्रथाभिः प्रयोज्यविधिभिश्च नियन्त्र्यते।`]},{heading:`१०. सुरक्षा सीमाश्च`,paragraphs:[`स्वनियन्त्रणक्षेत्रे युक्तियुक्तान् तान्त्रिकसुरक्षोपायान् कर्तुं RadioBee प्रयतते। तथापि कस्यापि तन्त्रांशस्य, उपकरणस्य, जालसम्पर्कस्य वा सञ्चयव्यवस्थायाः सम्पूर्णसुरक्षा निरन्तरोपलब्धिर्वा प्रत्याभातुं न शक्यते। स्वकीयपरिचालनप्रणालीं ब्राउजरं च अद्यतनं रक्षतु, उपकरणानुमतीः गोपनीयतानियन्त्रणानि च परीक्षताम्।`]},{heading:`११. बालकाः गोपनीयताधिकाराश्च`,paragraphs:[`RadioBee सामान्योपयोगाय वाणीकेन्द्रसूचीसेवा अस्ति; बालकेभ्यः वैयक्तिकसूचनाः अभ्यर्थयितुं न निर्मिता। यथोचितं मातापितरौ पालकाश्च बालकानां तृतीयपक्षीयवाणीसेवोपयोगं निरीक्षेरन्।`,`भवतः स्थानं प्रयोज्यविधिं च आश्रित्य वैयक्तिकदत्तांशविषये सूचना, प्रवेशः, संशोधनम्, मार्जनम्, शिकायतसमाधानं वा अन्योपायाश्च भवतः अधिकाराः भवितुम् अर्हन्ति। यत्र विधिना सम्पर्कमार्गः शिकायतसमाधानव्यवस्था वा अनिवार्या तत्र तदपेक्षितदत्तांशसङ्ग्रहात् पूर्वं सञ्चालकेन सा प्रदातव्या।`]},{heading:`१२. परिवर्तनानि सम्पर्कश्च`,paragraphs:[`अनुप्रयोगे परिवर्तनात् वैधानिकापेक्षाणां विकासाद्वा एषा नीतिः नवीकर्तुं शक्यते। महत्वपूर्णपरिवर्तनानि संशोधितप्रभाविदिनाङ्केन सह अस्मिन् पृष्ठे दर्शयिष्यन्ते। अस्याः नीतेः विषये प्रश्नार्थं निवेदनार्थं च RadioBee सम्पर्कप्रपत्रं प्रयुङ्क्ताम्। प्रविष्टयः Google Forms माध्यमेन प्रेष्यन्ते; ब्राउजरे प्रेषणेन एव सन्देशस्य वितरणं प्राप्तिर्वा प्रमाणिता न भवति।`]}]},terms:{title:`नियमाः शर्ताश्च`,summary:`तृतीयपक्षीयान्तर्जालवाणीसेवानां सूचीप्रदर्शनश्रवणसाधनस्य RadioBee इत्यस्य प्रवेशं उपयोगं च एते नियमाः नियन्त्रयन्ति। प्रभाविदिनाङ्कः — १७ नवम्बर २०२६।`,sections:[{heading:`१. स्वीकृतिः विधिसम्मतश्च उपयोगः`,paragraphs:[`RadioBee प्रवेशेन उपयोगेन वा भवान् एतान् नियमान् प्रयोज्यविधिं च पालयितुं सहमतिं ददाति। यदि सहमतिः नास्ति तर्हि सेवां मा प्रयुङ्क्ताम्। यदि कश्चन नियमः भवतः अधिकारक्षेत्रे विधिना अनपनेयैः अधिकारैः सह विरुध्यते तर्हि ते अनिवार्याधिकाराः प्रधानाः भवन्ति।`,`अनुप्रयोगं, प्रसारकजालस्थलानि, ध्वनिप्रवाहान् सम्बन्धितसामग्रीं च आवश्यकानुमतयः वैधानिकाधिकाराश्च सन्ति चेत् एव प्रयुङ्क्ताम्।`]},{heading:`२. RadioBee किं प्रददाति`,paragraphs:[`RadioBee उपयोक्तॄन् अन्तर्जालवाणीकेन्द्राणि अन्वेष्टुं श्रोतुं च साहाय्यं करोति। केन्द्रसूचयः, चिह्नानि, विवरणानि, श्रवणसम्बन्धाः च सार्वजनिकरूपेण उपलब्धेभ्यः स्रोतेभ्यः तृतीयपक्षप्रदातृभ्यो वा प्राप्ताः स्युः। कस्यचित् केन्द्रस्य सूच्याम् उपस्थितिः स्वामित्वस्य, भागीदारीसम्बन्धस्य, सम्बद्धतायाः, अनुज्ञापत्रस्य वा अनुमोदनस्य प्रमाणं नास्ति।`,`केन्द्रसम्बन्धैः प्रदर्शितानां तृतीयपक्षीयवाणीकार्यक्रमाणां प्रसारकः, निर्माता, प्रकाशकः, अधिकारधारकः वा RadioBee नास्ति। प्रवाहस्य उपलब्धिः प्रवेशशर्ताश्च स्वतन्त्रप्रदातृभिः निर्धारिताः भवन्ति।`]},{heading:`३. ध्वनिप्रवाहाणां तृतीयपक्षीयसामग्र्याश्च स्वामित्वम्`,paragraphs:[`RadioBee कस्यापि तृतीयपक्षीयध्वनिप्रवाहस्य, प्रसारणस्य, सङ्गीतस्य, कार्यक्रमस्य, सम्प्रेषणस्य, केन्द्रव्यापारचिह्नस्य वा प्रसारकचिह्नस्य स्वामित्वं न प्रतिपादयति। ते अधिकाराः सम्बन्धितस्वामिनां अनुज्ञादातॄणां च सन्ति।`,`RadioBee नाम, मूलोपयोगकर्ता-अन्तर्मुखम्, मूलप्रलेखनं तथा अनुप्रयोगस्य अन्या मूलसामग्री पृथक् संरक्षिता भवितुम् अर्हति। अत्र किमपि विधानम् अनुप्रयोगस्य तृतीयपक्षीयसामग्र्याश्च अधिकारान् अन्यस्मै न हस्तान्तरयति।`]},{heading:`४. ध्वनिप्रवाहसम्बन्धाः प्रसारकनियन्त्रणं च`,paragraphs:[`वाणीकेन्द्राणि प्रसारणसेवाप्रदातारश्च पूर्वसूचनां विना सेवां परिवर्तयितुं, भौगोलिकरूपेण प्रतिबन्धयितुं, अवरोद्धुं, समाप्तुं, आयार्जनार्थं प्रयोजयितुं वा प्रवेशं निवारयितुं शक्नुवन्ति। केन्द्रप्रविष्टिः प्रवाहसम्बन्धो वा कदाचिदपि अशुद्धः, अनुपलब्धः, निषिद्धः, पुरातनः वा भवेत्।`,`केन्द्रनाम्नः, अतिरिक्तदत्तांशस्य, भाषायाः, अनुज्ञास्थितेः, प्रवाहगुणस्य, सङ्केतस्य निरन्तरतायाः, सम्पादकीयसामग्र्याः, निरन्तरोपलब्धेश्च विषये RadioBee प्रत्याभूतिं न ददाति।`]},{heading:`५. तृतीयपक्षीयप्रवाहाणाम् उपयोगः`,paragraphs:[`सार्वजनिकरूपेण श्रवणीयः प्रवाहः उपलब्धः इत्येव कारणेन तस्य सामग्र्याः प्रतिलिपिकरणस्य, पुनःप्रसारणस्य, पुनर्वितरणस्य, सार्वजनिकप्रदर्शनस्य वा वाणिज्योपयोगस्य अधिकारः न लभ्यते। सामान्यतः अनुमतश्रवणात् परे उपयोगाय आवश्यकानाम् अनुमतीनां प्राप्तिः भवतः उत्तरदायित्वम्।`,`सुरक्षानियन्त्रणानि लङ्घयितुं, प्रवेशप्रतिबन्धान् परिहर्तुं, तृतीयपक्षाधिकारान् उल्लङ्घयितुं, अननुज्ञातप्रसारणवितरणं कर्तुं वा RadioBee मा प्रयुङ्क्ताम्। युक्तियुक्ताधिकारविवादे वैधानिकप्रतिबन्धे वा दृष्टे RadioBee केन्द्रप्रविष्टिं निष्कासयितुं सीमितुं वा शक्नोति।`]},{heading:`६. भवतः उत्तरदायित्वानि`,points:[`विधीन्, प्रसारकशर्तान्, अनुज्ञापत्राणि, अन्येषाम् अधिकारान् तथा उपयुज्यमानमञ्चस्य नियमांश्च पालयतु।`,`प्रतिलिप्यधिकारव्यापारचिह्नाधिकारयोः उल्लङ्घनाय, सुरक्षानियन्त्रणलङ्घनाय, हानिकरतन्त्रांशवितरणाय, अन्येषां उपयोक्तॄणां प्रदातॄणां वा विघ्नाय सेवां मा प्रयुङ्क्ताम्।`,`प्रसारणस्वामित्वं केन्द्रपरिचयं वा मिथ्या मा निरूपयतु; शिकायतप्रपत्रे अन्यस्य वैयक्तिकसूचनाः मा प्रकाशयतु।`,`स्वकीयम् उपकरणं खातानि च रक्षतु; बाह्यसम्बन्धान् सेवाश्च उद्घाटयितुं पूर्वम् अनुमतीः परीक्षताम्।`]},{heading:`७. तृतीयपक्षीयजालस्थलानि सेवाश्च`,paragraphs:[`सौकर्यार्थं बाह्यसम्बन्धाः प्रवाहाश्च प्रदीयन्ते। स्वतन्त्रजालस्थलानि, प्रसारकान्, विज्ञापनदातॄन्, संरचनाप्रदातॄन् अन्यान् वा तृतीयपक्षान् RadioBee न निरीक्षते, न चालयति, न प्रत्याभाति, न नियन्त्रयति। तैः सह भवतः व्यवहारः तेषां स्वकीयनियमानां नीतीनां च अधीनः अस्ति।`]},{heading:`८. सम्पादकीयसमर्थनाभावः`,paragraphs:[`केन्द्रप्रविष्टयः सूचनार्थम् एव सन्ति; ताः कस्यापि प्रसारकस्य, मतस्य, विज्ञापनस्य, राजनीतिकस्थितेः, चिकित्सोपदेशस्य, वित्तीयोपदेशस्य अन्यस्य वा प्रसारितविषयस्य RadioBee-समर्थनं न सूचयन्ति। प्रयोज्यविध्यनुसारं प्रसारकाः स्वप्रसारणानां सम्पादकीयनिर्णयानां च उत्तरदायिनः भवन्ति।`]},{heading:`९. सूचनायाः शुद्धता उपलब्धिश्च`,paragraphs:[`सेवा यथा उपलब्धा तथा प्रदीयते। प्रयोज्यविधिना अनुमतां पूर्णां सीमाम् अनुसृत्य RadioBee निरन्तरप्रवेशस्य, दोषरहितकार्यस्य, विशिष्टप्रयोजनयोग्यतायाः, तृतीयपक्षप्रसारणैः अधिकारानुल्लङ्घनस्य, केन्द्रसूचनानां शुद्धतायाः पूर्णतायाश्च प्रत्याभूतीः अस्वीकरोति।`,`सुरक्षायै, तान्त्रिककार्यार्थं, अधिकारपालनाय अन्येभ्यो वा युक्तियुक्तकारणेभ्यः RadioBee केन्द्रप्रविष्टिं, सम्बन्धं, सुविधां सेवां वा परिवर्तयितुं, स्थगयितुं, निष्कासयितुं समाप्तुं वा शक्नोति।`]},{heading:`१०. उत्तरदायित्वस्य सीमाः`,paragraphs:[`प्रयोज्यविधिना अनुमतां महत्तमां सीमाम् अनुसृत्य तृतीयपक्षीयप्रसारणेभ्यः, विघ्नेभ्यः, उपकरणासङ्गतेः, अनुपलब्धप्रवाहेभ्यः, स्थानीयदत्तांशनाशात् अथवा भवतः सेवोपयोगात् उत्पन्नानां परोक्षाणाम्, आकस्मिकाणाम्, विशेषाणाम्, परिणामजनितानाम् अथवा दण्डप्रदर्शनार्थकाणां हानीनां कृते RadioBee तस्य सञ्चालकाश्च उत्तरदायिनः न भवन्ति।`,`यदुत्तरदायित्वं विधिना न अपाकर्तुं न सीमितुं च शक्यते, तस्य अपवादः अथवा सीमा अनेन विधानेन न क्रियते। अनिवार्यवैधानिककर्तव्येभ्यः उत्पन्नम् उत्तरदायित्वम् अपि अस्मिन् अन्तर्भवति। एते नियमाः वैधानिकान् उपभोक्तृ-अधिकारान्, गोपनीयताधिकारान्, बौद्धिकसम्पदधिकारान् अन्यान् वा अनिवार्याधिकारान् न हरन्ति।`]},{heading:`११. भवतः दुरुपयोगस्य उत्तरदायित्वम्`,paragraphs:[`स्वकीयावैधानिकोपयोगस्य, अननुज्ञातपुनर्वितरणस्य, पराधिकारोल्लङ्घनस्य च भवान् उत्तरदायी अस्ति। प्रयोज्यविधिना यत्र अनुमतम्, तत्र भवतः जानन्नेव कृतदुरुपयोगात् एतेषां नियमानां गम्भीरलङ्घनाद्वा उत्पन्नान् तृतीयपक्षीयदावान् परिहर्तुं भवान् सहमतिं ददाति; RadioBee-स्वकीयावैधानिककर्मणा यावदंशः उत्पन्नः तावदंशः अपवादः।`]},{heading:`१२. बौद्धिकसम्पद्विषयकशिकायताः निष्कासनं च`,paragraphs:[`RadioBee बौद्धिकसम्पदधिकारान् प्रसारकाधिकारांश्च सम्मानयति। प्रमाणिताधिकारधारकाः, तेषाम् अधिकृतप्रतिनिधयः, समुचितप्रमाणयुक्तचिन्तायुक्ताश्च उपयोक्तारः विशिष्टकेन्द्रप्रविष्टेः, प्रवाहस्य URL, चिह्नस्य अन्यस्य वा विषयस्य शिकायतां प्रतिलिप्यधिकार-निष्कासननीतौ वर्णितप्रक्रियया निवेदयितुं शक्नुवन्ति।`,`विश्वसनीयाधिकारदावे, वैधन्यायादेशे, प्रमाणयुक्ताधिकारोल्लङ्घनशङ्कायां अन्यस्मिन् वा युक्तियुक्तकारणे सति RadioBee विवादितप्रविष्टिम् अन्वेष्टुं निष्कासयितुं निष्क्रियीकर्तुं वा शक्नोति। सूचीभ्यः निष्कासनं तृतीयपक्षीयसेवकैः नियन्त्रितानां प्रतिलिपीनां प्रसारणानां वा मार्जनं न करोति।`]},{heading:`१३. निरन्तरप्रवेशे एकमात्रं विश्वासं मा कुरुत`,paragraphs:[`RadioBee न आपत्कालीनसेवा, न सार्वजनिकसुरक्षासेवा, न च प्रत्याभूतसूचनासेवा अस्ति। तात्कालिकविपत्सूचनानां समयसंवेदनशीलनिर्देशानां वा एकमात्रस्रोतःरूपेण अन्तर्जालवाणीप्रवाहं मा आश्रयतु।`]},{heading:`१४. प्रयोज्यविधिः विवादाश्च`,paragraphs:[`सेवोपयोगः सम्बन्धितकर्मणः, स्थानस्य, पक्षाणां च प्रयोज्यविधीनाम् अधीनः अस्ति। विवादसमाधानस्य न्यायाधिकरणस्य वा काऽपि अपेक्षा अनिवार्यविधीनां प्रयोज्योपभोक्तृसंरक्षणनियमानां च अधीना भवति। एते नियमाः एकमेव न्यायालयं न निर्दिशन्ति, अनपनेयान् उपायान् वा न त्यजन्ति।`]},{heading:`१५. परिवर्तनानि, प्रावधानानां पृथक्स्थितिः सम्पर्कश्च`,paragraphs:[`सुविधानां, बाह्यसेवानां, वैधानिकापेक्षाणां च परिवर्तने RadioBee एतान् नियमान् संशोधयितुं शक्नोति। अस्मिन् पृष्ठे प्रदत्तदिनाङ्कः प्रवर्तमानसंस्करणं दर्शयति। यदि किञ्चित् प्रावधानं अवैधं निश्चितं भवति तथापि विधिना अनुमतपर्यन्तं अन्यानि प्रावधानानि प्रवर्तन्ते।`,`प्रश्नसंशोधनार्थं सम्पर्कप्रपत्रं प्रयुङ्क्ताम्। ब्राउजरः Google Forms प्रति अनुरोधं प्रेषयति किन्तु Google इत्यस्मात् पृथक् प्राप्तिप्रमाणं न प्राप्नोति; अतः प्रदर्शितः प्रेषणसमाप्तिसन्देशः ब्राउजरानुरोधस्य समाप्तिम् एव बोधयति, न तु सन्देशः RadioBee-सञ्चालकं प्राप्तः अथवा तेन पठितः इति प्रमाणयति।`]}]},"copyright-policy":{title:`प्रतिलिप्यधिकार-निष्कासननीतिः`,summary:`RadioBee प्रसारणानां, सङ्गीतस्य, कार्यक्रमाणां, व्यापारचिह्नानाम् अन्येषां च तृतीयपक्षीयाधिकाराणां सम्मानं करोति। प्रमाणसमर्थितशिकायताः परीक्ष्य यथोचितं केन्द्रप्रविष्टयः निष्कासयिष्यामः निष्क्रियीकरिष्यामः वा। प्रभाविदिनाङ्कः — १७ नवम्बर २०२६।`,sections:[{heading:`१. तृतीयपक्षीयप्रवाहेषु स्वामित्वाभावः`,paragraphs:[`RadioBee स्वतन्त्रः वाणीकेन्द्रान्वेषणश्रवणानुप्रयोगः अस्ति। तृतीयपक्षीयप्रवाहाणां, सङ्गीतस्य, कार्यक्रमाणां, प्रसारणानां, केन्द्रनाम्नां चिह्नानां च स्वामित्वं न धारयति, तान् न निर्माति, प्रसारकाणां प्रतिनिधिरूपेण अनुज्ञां न ददाति, तेषां अधिकारान् न प्रतिपादयति। ते अधिकाराः प्रसारकाणां, प्रतिलिप्यधिकारस्वामिनाम्, सम्बन्धितानुज्ञादातॄणां च सन्ति।`,`RadioBee-सूच्याम् केन्द्रस्य उल्लेखः तस्य प्रसारकेण अनुप्रयोगाय प्रायोजनं, समर्थनम्, अनुज्ञा, अनुमतिः वा दत्ता इत्यर्थं न बोधयति।`]},{heading:`२. निष्कासनसंशोधनयोः प्रतिबद्धता`,paragraphs:[`अननुज्ञातप्रविष्टिषु, अधिकारविवादेषु, अशुद्धपरिचयेषु, निषिद्धप्रवेशे अथवा अन्येषु युक्तियुक्तविषयेषु स्पष्टपरिचिताः सद्भावपूर्वकाः शिकायताः समीक्षितुं वयं प्रयतामहे। विश्वसनीयप्रमाणं वैधविध्याधारो वा कार्यवाहीं समर्थयति चेत् RadioBee केन्द्रप्रविष्टिं, चिह्नं, विवरणं, प्रवाहसम्बन्धं, सुविधां वा शीघ्रं निष्कासयितुं निष्क्रियीकर्तुं संशोधयितुं वा शक्नोति।`,`शिकायतायाः समीक्षाकाले RadioBee तात्कालिकरूपेण प्रवेशं सीमितुं शक्नोति। निर्णयाः उपलब्धसूचनानां प्रयोज्यविधेश्च आधारेण क्रियन्ते; शिकायताप्रदानमात्रेण विशिष्टपरिणामस्य प्रत्याभूतिः न भवति।`]},{heading:`३. शिकायतायां देयानि विवरणानि`,points:[`केन्द्रस्य नाम, RadioBee-सूच्याम् तस्य यथार्थः URL, ज्ञातौ सति सम्बन्धितप्रवाहस्य चित्रस्य वा URL।`,`विवादितं कृतिः, व्यापारचिह्नं, प्रसारणम् अथवा अधिकारः तथा चिन्तायाः स्पष्टविवरणम्।`,`भवतः अधिकारस्य प्रतिनिधित्वाधिकारस्य वा वैधानिकः वास्तविकश्च आधारः, अगोपनीयसमर्थकविवरणैः सह।`,`विशिष्टतया याचितः उपायः — संशोधनं, निष्कासनं, श्रवणनिष्क्रियीकरणम् अथवा अन्यः यथोचितोपायः।`,`अनुवर्तनार्थं विद्युत्पत्रसङ्केतः; संवेदनशीलसमर्थकवस्तूनि आवश्यकानि चेत् वैकल्पिकसुरक्षितसम्पर्कमार्गस्य अनुरोधश्च।`]},{heading:`४. शिकायतासम्पर्कमार्गः`,paragraphs:[`चिन्तां निवेदयितुं, विशिष्टकेन्द्रप्रविष्टिं निर्देष्टुं, अपेक्षितोपायं वर्णयितुं च RadioBee सम्पर्कप्रपत्रं प्रयुङ्क्ताम्। प्रपत्रदत्तांशाः परियोजनासञ्चालकस्य अवलोकनार्थं Google Forms प्रति प्रेष्यन्ते। एतत् गोपनीयवैधानिकसूचनानां द्वारं नास्ति, न च प्रत्याभूतप्राप्तिव्यवस्था।`,`परिचयपत्राणि, पत्ताविवरणानि, निजीअनुबन्धान्, अप्रकाशितकृतीः, प्रवेशप्रमाणानि अथवा संवेदनशीलप्रमाणानि सम्पर्कप्रपत्रे मा प्रेषयतु। यदि संवेदनशीलप्रमाणम् आवश्यकं तर्हि प्रथमं योग्यं सुरक्षितसम्पर्कमार्गं याचताम्।`]},{heading:`५. समीक्षा कार्यवाही च`,paragraphs:[`उपलब्धमार्गे शिकायतायां प्राप्तायां परियोजना केन्द्रस्य URL, स्रोतसूचनाः, उपलब्धाधिकारविवरणानि, प्रसारकप्रतिबन्धान्, याचितोपायं च परीक्षितुं शक्नोति। यदि शिकायताऽपूर्णा विवादिता वा अस्ति तर्हि स्पष्टीकरणं याचितुं शक्यते।`,`युक्तियुक्तप्रमाणसमर्थितचिन्ताभ्यः सूचीप्रविष्टेः निष्कासनं, श्रवणप्रवेशस्य सीमा अथवा स्वामित्वविवरणसंशोधनं सम्भवति। प्रसारकसेवाप्रदातृभिः चालितायाम् आधारसंरचनायाम् विद्यमानं मूलप्रवाहं RadioBee न निष्कासयितुं न नियन्त्रयितुं शक्नोति। विध्यनुसारं वैधवैधानिकसूचनाः न्यायालयादेशाश्च विचारयिष्यन्ते।`]},{heading:`६. प्रसारकानुमतिः उपयोगप्रतिबन्धाश्च`,paragraphs:[`प्रवाहस्य सार्वजनिकोपलब्धिः एव तस्य पुनर्वितरणस्य, पुनःप्रसारणस्य, वाणिज्योपयोगस्य वा केन्द्रचिह्नोपयोगस्य अनुमतिं न सिद्धयति। उपयोक्तारः प्रयोज्याधिकारान्, प्रसारकशर्तान्, स्वकार्येभ्यः आवश्यकानुमतीश्च सम्मानयन्तु।`]},{heading:`७. सद्भावपूर्णशिकायताः परस्परविरोधिनः अधिकाराश्च`,paragraphs:[`सत्यसूचनाः प्रेषयन्तु; अधिकारस्वामिनः मिथ्याभिनयं जानन्नेव मा कुर्वन्तु, असत्यवचनानि च मा प्रेषयन्तु। केन्द्रसञ्चालकः अथवा अन्यः प्रभावितः पक्षः योग्यसम्पर्कमार्गेण संशोधनानि अनुमतिप्रमाणानि वा निवेदयितुं शक्नोति।`,`निर्णयात् पूर्वं RadioBee स्वामित्वम्, अनुज्ञापत्राणि, वैधानिकापवादान्, अनुमतीः, प्रसारकनिर्देशान्, विवादितप्रविष्टेः परिस्थितीश्च परिशीलयितुं शक्नोति। यावत् विधिना अनिवार्यं न भवति तावत् अत्र औपचारिकप्रतिसूचनाप्रक्रिया विवादसमाधानव्यवस्था वा अस्ति इति न गन्तव्यम्।`]},{heading:`८. व्यापारचिह्नानि केन्द्रपरिचयाश्च`,paragraphs:[`तृतीयपक्षीयकेन्द्रनामानि, व्यापारचिह्नानि, चित्राणि च सम्बन्धितसेवापरिचयार्थम् एव उपयुज्यन्ते। तेषाम् उपयोगः प्रायोजनं, समर्थनं, स्वामित्वहस्तान्तरणं वा न बोधयति। अशुद्धचिह्नप्रयोगम् अननुज्ञातचित्राणि च अधिकारधारकाः समीक्षार्थं निवेदयितुं शक्नुवन्ति।`]},{heading:`९. पुनरावृत्तसमस्याः नवीकरणानि च`,paragraphs:[`यदा एकस्मिन् स्रोते पुनःपुनः समस्याः भवन्ति तदा RadioBee सम्बन्धितप्रविष्टयः सुविधाश्च यथोचितं प्रतिबन्धयितुं निष्कासयितुं वा शक्नोति। सम्पर्कप्रेषणे, अधिकारसत्यापने, वैधानिककर्तव्येषु वा परिवर्तने एषा नीतिः नवीकर्तुं शक्यते। विध्यपेक्षितशिकायतासमाधानप्रक्रिया सूचनाप्रक्रिया वा अस्मात् सामान्यविवरणात् प्राधान्यं लभते।`]}]},contact:{title:`सम्पर्कं करोतु`,summary:`प्रश्नाः, केन्द्रविवरणसंशोधनानि, प्रसारकाधिकारसम्बद्धचिन्ताः अथवा परामर्शाः सन्ति वा? RadioBee सम्पर्कप्रपत्रम् उद्घाटयितुं अधः विषयं चिनोतु।`,sections:[{heading:`RadioBee सम्पर्कः`,paragraphs:[`स्वनाम, विद्युत्पत्रसङ्केतं तथा प्रश्नस्य प्रयोजनं ददातु। केन्द्रविवरणानि ऐच्छिकानि सन्ति। प्रपत्रप्रेषणेन भवतः प्रविष्टयः संसाधनार्थं तथा RadioBee-प्रपत्रसञ्चालकस्य अवलोकनार्थं Google Forms प्रति प्रेष्यन्ते।`,`प्रेषणमात्रेण प्रत्युत्तरस्य प्रत्याभूतिः न भवति, न च प्रमाणितवैधानिकसूचनामार्गः स्थाप्यते। गोपनीयपत्राणि, गुप्तशब्दान्, संवेदनशीलवैयक्तिकसूचनाश्च मा समावेशयतु।`]}]}};var l={privacy:{heading:`१३. प्रायोगिकध्वनिमुद्रणं स्थानीयसञ्चितध्वनिश्च`,paragraphs:[`यदा ऐच्छिकप्रायोगिकध्वनिमुद्रणसुविधा सक्रियास्ति तदा उपयोक्तुः उपकरणे ध्वनिः मुद्र्यते, सञ्चिकाश्च तेन चिते सञ्चयस्थाने रक्ष्यन्ते निर्यात्यन्ते वा। RadioBee स्वसेवकेषु एतानि मुद्रणानि न आरोपयति न च तत्र आतिथ्येन सञ्चिनोति। सञ्चितसञ्चिकानां नियन्त्रणं उपयोक्तुः एव; उपकरणस्य प्रतिरक्षासेवाः, सञ्चयप्रदातारः, वितरणार्थोपयुक्ताः अनुप्रयोगाश्च स्वकीयनियमानां व्यवस्थायाश्च अनुसारं तासां प्रतिलिपीः संसाधयितुं शक्नुवन्ति।`,`मुद्रणेषु प्रतिलिप्यधिकारसंरक्षितप्रसारणानि कार्यक्रमेषु उच्चारिताः वैयक्तिकसूचनाश्च समाविष्टाः स्युः। मुद्रणस्य विधिसम्मतानां निर्माणस्य, धारणस्य, संरक्षणस्य, मार्जनस्य, उत्तरवितरणस्य उपयोगस्य च उत्तरदायित्वं मुद्रणकर्तुः एव।`]},terms:{heading:`१६. प्रायोगिकध्वनिमुद्रणसुविधा उपयोक्तुरुत्तरदायित्वं च`,paragraphs:[`ऐच्छिकध्वनिमुद्रणसुविधा स्थानीयध्वनिग्रहणस्य, सञ्चयस्य, रूपान्तरणस्य, उपकरणसङ्गतेश्च परीक्षणार्थं प्रदत्ता प्रायोगिकसुविधा अस्ति। एषा अनुज्ञाप्राप्तध्वनिमुद्रणसेवा नास्ति, न निरन्तरग्रहणस्य सञ्चिकापुनर्प्राप्तेर्वा प्रत्याभूतिः, न च तृतीयपक्षीयप्रसारणं मुद्रयितुम् अनुमतिः।`,`यः जनः मुद्रणं चिनोति स एव तस्य आरम्भस्य, किं रक्षणीयं वितरणीयं वेति निर्णयस्य, प्रसारकेभ्यः अन्येभ्यो अधिकारधारकेभ्यश्च आवश्यकानुमतिप्राप्तेः, प्रतिलिप्यधिकारस्य, गोपनीयतायाः, प्रसारकशर्तानां प्रयोज्यविधीनां च पालनस्य एकमात्रः उत्तरदायी। यत्र ध्वनिमुद्रणं, प्रतिलिपिकरणं, वितरणम् अन्यो वा उपयोगः निषिद्धः तत्र तानि कर्माणि मा कुरुत।`,`RadioBee, तस्य स्वामी, निर्मातारः, योगदानकर्तारः, सञ्चालकाश्च उपयोक्तृकृतध्वनिमुद्रणानि न आरभन्ते, न निर्देशयन्ति, न पर्यवेक्षन्ते, न स्वसेवकेषु सञ्चिन्वन्ति, न वितरन्ति। प्रयोज्यविधिना अनुमतां महत्तमां सीमाम् अनुसृत्य उपयोक्त्रा निर्मितानां, धारितानां, वितरितानां, दुरुपयुक्तानां च मुद्रणानां तस्य आचरणादुत्पन्नदावानां च उत्तरदायित्वं विधिकृतदायित्वं च ते अस्वीकुर्वन्ति। यदुत्तरदायित्वं विधिना न अपाकर्तुं न सीमितुं च शक्यते तत् एषा सूचना न अपाकरोति।`]},"copyright-policy":{heading:`१०. उपयोक्त्रा आरब्धानि प्रायोगिकध्वनिमुद्रणानि`,paragraphs:[`उपकरणे ध्वनिग्रहणस्य निर्यातस्य च परीक्षणार्थम् ऐच्छिकमुद्रणसुविधा प्रदत्ता अस्ति। तस्याः उपलब्धिमात्रेण वाणीप्रसारणानां प्रतिलिप्यधिकारसंरक्षितायाः अन्यसामग्र्याश्च मुद्रणस्य, प्रतिलिपिकरणस्य, वितरणस्य, प्रकाशनस्य अथवा वाणिज्योपयोगस्य अनुज्ञा अधिकारो वा न प्राप्यते।`,`प्रत्येकं मुद्रणं स्वयम् उपयोक्ता आरभते नियन्त्रयति च। आवश्यकानुमतिप्राप्तेः प्रयोज्याधिकाराणां विधीनां प्रसारकप्रतिबन्धानां च पालनस्य स एव एकमात्रः उत्तरदायी। RadioBee, तस्य स्वामी सञ्चालकाश्च उपयोक्तृमुद्रणानां निर्मातारः वितारकाश्च न सन्ति; विधिना अनुमतसीमायां व्यक्तिभिः कृतस्य अननुज्ञातमुद्रणस्य उपयोगस्य वा विधिकृतदायित्वं न स्वीकुर्वन्ति। अनिवार्यवैधानिककर्तव्यानि अधिकाराश्च अप्रभावितानि तिष्ठन्ति।`]}};var h={privacy:{title:`Privacy Policy`,summary:`This policy explains what RadioBee stores on your device, what may be shared with third-party streaming services, and the limits of our control over those services. Effective 17 November 2026.`,sections:[{heading:`1. Scope and the service`,paragraphs:[`RadioBee is an internet radio discovery and playback application. This policy applies to the RadioBee website and features provided by the application. It does not replace the separate privacy notices or practices of broadcasters, streaming hosts, operating systems, app stores, or websites that you visit through RadioBee.`,`RadioBee operates as a directory and player for third-party audio streams. The broadcasters and their hosting services independently determine how their servers process network requests and associated information.`]},{heading:`2. Information stored in the application`,paragraphs:[`The current application saves preferences and functional data on your device using browser or platform storage. Depending on the features you use, this may include favorites, interface language, theme, home-station selections, and cached catalogue data.`,`Clearing site data, changing browsers, or uninstalling the app may remove these locally stored preferences. Browser and operating-system controls determine the availability and persistence of local storage.`]},{heading:`3. Radio listening and third-party network requests`,paragraphs:[`Playing a station connects your device to the relevant broadcaster or streaming provider. Those third parties may receive technical information inherent in a network request, such as your IP address, device and browser details, request time, and stream URL. Their collection, cookies, logging, geographic restrictions, and retention practices are outside RadioBee’s control.`,`Catalogue and application resources may be requested from GitHub Pages or other configured infrastructure. These hosting providers may process technical request logs under their own policies.`]},{heading:`4. Device storage and preferences`,paragraphs:[`RadioBee uses local device storage to remember supported user preferences and, where available, cache station-directory information. This allows features such as saved favorites and interface settings to function across visits.`,`Your browser or operating system may clear stored information because of your own settings, storage limits, privacy modes, or maintenance. RadioBee cannot guarantee that device-stored preferences will remain available indefinitely.`]},{heading:`5. Information you choose to submit`,paragraphs:[`RadioBee provides a Contact Us form that submits through a third-party service, Google Forms. If you submit it, the details you enter (such as name, email, optional phone number, inquiry purpose, message, and optional station information) are transmitted to Google for processing and made available to the RadioBee form operator. The form does not store its entries as RadioBee browser preferences.`,`Google processes form submissions under its own terms and privacy practices. Providing an inquiry and agreeing to submission are voluntary; do not send passwords, identity documents, sensitive contractual information, or other confidential material unless an appropriate secure channel has been agreed separately.`]},{heading:`6. Cookies, analytics and advertising`,paragraphs:[`RadioBee uses device and browser storage for application functionality, as described above. This policy does not promise that every third-party streaming host, browser, operating system, or hosting provider operates without cookies, analytics, advertising technologies, or logs.`,`If RadioBee later adds its own analytics, advertising integrations, authentication, or another server-hosted contact system, this policy must be reviewed and updated to describe those features and any choices or notices legally required.`]},{heading:`7. Purposes and legal requirements`,paragraphs:[`Functional data is used to provide playback, saved preferences, station discovery, and normal operation of the application. Any information processed by infrastructure providers may also be necessary to deliver and secure network services.`,`Where applicable law requires consent, a legal basis, or a specific notice for personal data processing, those legal requirements apply in addition to this policy. Nothing in this document is intended to waive statutory privacy rights.`]},{heading:`8. Retention and control`,paragraphs:[`You can usually remove stored RadioBee preferences and cached catalogue data by clearing the app or browser’s site data, subject to the platform. RadioBee does not control deletion or retention of information held by broadcasters, streaming providers, or other independent services.`,`Contact form entries may be stored and retained by Google Forms and by the form operator according to their respective settings and applicable legal obligations. RadioBee does not currently provide a user-facing deletion workflow for submitted Google Forms responses. Use the Contact Us form for inquiries or requests about submitted information, and do not send sensitive documents through it.`]},{heading:`9. Sharing and international access`,paragraphs:[`RadioBee does not need to sell locally stored favorites or preferences to provide its core directory and playback features. Your device necessarily makes connections to selected streaming and hosting providers, which may operate from other regions or countries. Each provider’s handling of request data is governed by its own practices and applicable law.`]},{heading:`10. Security and limitations`,paragraphs:[`RadioBee aims to use reasonable technical safeguards within its control, but no software, device, internet connection, or storage system can be guaranteed completely secure or continuously available. You should keep your operating system and browser updated and review the permissions and privacy controls on your device.`]},{heading:`11. Children and privacy rights`,paragraphs:[`RadioBee is a general-purpose directory and is not designed to solicit personal information from children. Parents and guardians should supervise children’s use of third-party radio services where appropriate.`,`Depending on your location and applicable law, you may have rights to information, access, correction, erasure, grievance redressal, or other remedies concerning personal data. The operator must provide any legally required contact or grievance mechanism before collecting information for which such a mechanism is mandatory.`]},{heading:`12. Changes and contact`,paragraphs:[`This policy may be updated when the application changes or legal requirements develop. Material updates will be reflected on this page with a revised effective date. Use the available RadioBee Contact Us form for questions or requests about this policy. The form sends entries through Google Forms; a browser submission does not verify delivery or receipt.`]}]},terms:{title:`Terms & Conditions`,summary:`These terms govern access to and use of RadioBee, a directory and playback interface for third-party internet radio services. Effective 17 November 2026.`,sections:[{heading:`1. Acceptance and lawful use`,paragraphs:[`By accessing or using RadioBee, you agree to comply with these terms and applicable law. If you do not agree, do not use the service. If any term conflicts with rights that cannot lawfully be restricted in your jurisdiction, those mandatory rights prevail.`,`You must use the app, broadcaster websites, streams, and related content only when you have the necessary permissions and legal rights.`]},{heading:`2. What RadioBee provides`,paragraphs:[`RadioBee helps users discover and listen to internet radio stations. Station listings, logos, descriptive information, and playback links may originate from publicly accessible sources or third-party providers. Station inclusion is not a statement of ownership, partnership, affiliation, licensing, or endorsement.`,`RadioBee is not itself the broadcaster, producer, publisher, or rights holder of the third-party radio programming offered through station links. Streaming availability and access conditions are set by independent providers.`]},{heading:`3. Ownership of streams and third-party content`,paragraphs:[`RadioBee does not claim ownership of any third-party radio stream, broadcast, music, program, transmission, station trademark, or broadcaster-owned logo. Those rights remain with their respective owners and licensors.`,`The RadioBee name, original interface, original documentation, and other original application materials may be protected separately. Nothing here transfers rights to the app or to third-party content.`]},{heading:`4. Stream links and broadcaster control`,paragraphs:[`Stations and streaming hosts can modify, geo-restrict, interrupt, discontinue, monetize, or block access to their services without notice. A listing or stream link may become incorrect, inaccessible, prohibited, or outdated at any time.`,`RadioBee does not guarantee a station’s title, metadata, language, licensing status, stream quality, signal continuity, editorial content, or continued availability.`]},{heading:`5. Use of third-party streams`,paragraphs:[`Access to a publicly available stream does not necessarily grant a right to reproduce, retransmit, redistribute, publicly perform, or commercially exploit its content. You are responsible for obtaining any permissions required for uses beyond ordinary authorized listening.`,`Do not use RadioBee to bypass security controls, defeat access restrictions, infringe third-party rights, or redistribute broadcasts without authorization. RadioBee may remove or restrict a station listing when a valid rights concern or legal restriction is identified.`]},{heading:`6. Your responsibilities`,points:[`Comply with laws, broadcaster terms, licenses, rights of third parties, and the conditions of any platform you use.`,`Do not use the service to infringe copyrights or trademarks, bypass security controls, distribute malicious code, or interfere with other users or providers.`,`Do not misrepresent ownership of broadcasts or station identities, or publish another person’s private information through an issue report.`,`Protect your own device and accounts, and review permissions before opening external links or services.`]},{heading:`7. Third-party sites and services`,paragraphs:[`External links and streams are provided for convenience. RadioBee does not supervise, operate, warrant, or control independent websites, broadcasters, advertisers, hosting providers, or other third parties. Your interactions with those entities are subject to their own terms and policies.`]},{heading:`8. No editorial endorsement`,paragraphs:[`Station listings are informational and do not constitute RadioBee’s endorsement of any broadcaster, viewpoint, advertisement, political position, medical advice, financial advice, or other streamed content. Broadcasters are responsible for their own transmissions and editorial decisions to the extent provided by applicable law.`]},{heading:`9. Accuracy and availability`,paragraphs:[`The service is offered on an as-available basis. To the fullest extent permitted by applicable law, RadioBee disclaims warranties concerning uninterrupted access, error-free operation, fitness for a particular purpose, non-infringement of third-party broadcasts, and the accuracy or completeness of station information.`,`RadioBee may modify, suspend, remove, or discontinue any station listing, link, feature, or service where reasonably necessary for safety, technical operation, rights compliance, or other legitimate reasons.`]},{heading:`10. Limitation of liability`,paragraphs:[`To the maximum extent permitted by applicable law, RadioBee and its operators are not liable for indirect, incidental, special, consequential, or exemplary losses arising from third-party broadcasts, interruptions, device incompatibility, unavailable streams, lost local data, or your use of the service.`,`This provision does not exclude or limit liability that cannot lawfully be excluded, including liability arising from obligations that applicable law makes non-waivable. Nothing in these terms removes statutory consumer, privacy, intellectual-property, or other mandatory rights.`]},{heading:`11. Responsibility for your misuse`,paragraphs:[`You are responsible for your own unlawful use, unauthorized redistribution, and violations of others’ rights. Where permitted by applicable law, you agree to address third-party claims arising from your willful misuse or material breach of these terms, except to the extent caused by RadioBee’s own unlawful conduct.`]},{heading:`12. Intellectual-property complaints and removal`,paragraphs:[`RadioBee respects intellectual-property and broadcaster rights. Verified rights holders, authorized representatives, and users with substantiated concerns may report a specific station listing, stream URL, logo, or other item through the process described in Copyright & Removal.`,`RadioBee may investigate and remove or disable a contested listing when there is a credible rights claim, valid legal order, substantiated infringement concern, or other legitimate reason. Removal from the directory cannot delete copies or broadcasts controlled by third-party servers.`]},{heading:`13. No reliance on continuous access`,paragraphs:[`RadioBee is not an emergency, public-safety, or guaranteed information service. Do not rely on an internet radio stream as your only source of urgent warnings or time-critical instructions.`]},{heading:`14. Applicable law and disputes`,paragraphs:[`Use of the service is subject to the laws applicable to the particular conduct, location, and parties. Any dispute resolution or forum requirements are subject to mandatory laws and applicable consumer protections. These terms do not designate an exclusive court or waive non-waivable remedies.`]},{heading:`15. Changes, severability and contact`,paragraphs:[`RadioBee may revise these terms as features, external services, and legal requirements change. The date on this page identifies the version in effect. If one provision is held invalid, other provisions remain effective to the extent lawful.`,`Use the Contact Us form for inquiries and corrections. Because the browser sends the request to Google Forms without access to a private receipt confirmation from Google, an on-screen submission message indicates that the browser request completed, not that the message was delivered to or read by the RadioBee operator.`]}]},"copyright-policy":{title:`Copyright & Removal Policy`,summary:`RadioBee respects broadcast, music, program, trademark, and other third-party rights. We will review substantiated complaints and remove or disable directory entries when warranted. Effective 17 November 2026.`,sections:[{heading:`1. No ownership of third-party streams`,paragraphs:[`RadioBee is an independent station-discovery and playback application. It does not own, produce, license on behalf of broadcasters, or claim rights over third-party radio streams, music, programs, transmissions, station brands, or logos. Rights remain with the broadcasters, copyright owners, and their respective licensors.`,`A station’s appearance in the RadioBee directory does not mean that the broadcaster has sponsored, endorsed, licensed, or authorized the app.`]},{heading:`2. Removal and correction commitment`,paragraphs:[`We aim to review clearly identified, good-faith reports of unauthorized listings, rights conflicts, inaccurate attribution, prohibited access, or other legitimate concerns. Where credible evidence or a valid legal basis warrants action, RadioBee may promptly remove, disable, or correct a station listing, logo, description, stream link, or feature.`,`RadioBee may also temporarily restrict access while a claim is reviewed. Decisions are assessed according to the information available and applicable law; filing a report does not guarantee a particular outcome.`]},{heading:`3. Information to include in a report`,points:[`The station name, the exact RadioBee listing URL, and the relevant stream or artwork URL if known.`,`The work, trademark, broadcast, or right at issue and a clear description of the concern.`,`The legal or factual basis for your rights or authority to act, with non-confidential supporting details.`,`The specific action requested: correction, removal, disabling of playback, or another appropriate remedy.`,`A contact email address for follow-up, and a request for an alternative secure channel if sensitive supporting material is required.`]},{heading:`4. Reporting channel`,paragraphs:[`Use the RadioBee Contact Us form to report concerns, identify the specific listing and describe the requested remedy. The form submits details to Google Forms for access by the project operator; it is not a confidential legal-notice portal or a guaranteed receipt system.`,`Do not submit identity documents, addresses, private contracts, unpublished works, credentials, or sensitive evidence through the contact form. If sensitive evidence is necessary, request a suitable secure channel first.`]},{heading:`5. Review and action`,paragraphs:[`When a report is received through an available channel, the project may check the station URL, source information, available rights details, any broadcaster restrictions, and the requested remedy. We may request clarification before acting where the report is incomplete or disputed.`,`Reasonably supported concerns may result in removal, restricted playback access, or corrected attribution. RadioBee cannot remove or control the underlying stream on infrastructure operated by a broadcaster or hosting service. Appropriate legal notices or court orders will be addressed according to applicable requirements.`]},{heading:`6. Broadcaster consent and use restrictions`,paragraphs:[`A stream being publicly accessible does not by itself establish permission for redistribution, retransmission, commercial use, or use of station branding. Users must respect applicable rights, broadcaster conditions, and any permissions required for their activities.`]},{heading:`7. Good-faith reports and competing rights`,paragraphs:[`Please submit accurate information and do not knowingly impersonate a rights holder or make false statements. A station operator or other affected party may present relevant corrections or authorization evidence through an appropriate reporting channel.`,`RadioBee may consider rights ownership, licenses, legal exceptions, permissions, broadcaster instructions, and the circumstances of a disputed listing before determining an action. No formal statutory counter-notice or dispute process is implied unless legally applicable.`]},{heading:`8. Trademarks and station identities`,paragraphs:[`Third-party station names, trademarks, and artwork are used only to identify the referenced services. Their inclusion does not convey sponsorship, endorsement, or transfer of ownership. Rights holders may report inaccurate branding or unauthorized imagery for review.`]},{heading:`9. Repeat issues and updates`,paragraphs:[`Where recurring issues involve the same source, RadioBee may block or remove related listings or features as appropriate. This policy may be updated to reflect changes to contact submission, rights verification, or legal obligations. Any legally required grievance or notice procedure takes precedence over this general description.`]}]},contact:{title:`Contact Us`,summary:`Questions, station corrections, broadcaster rights concerns or suggestions? Choose a topic below to open the RadioBee contact form.`,sections:[{heading:`Contact RadioBee`,paragraphs:[`Provide your name, email and the purpose of your inquiry. Station details are optional. Submitting the form shares your entries with Google Forms for processing and access by the RadioBee form operator.`,`Submitting does not guarantee a response or establish a verified legal-notice channel. Please avoid including confidential documents, passwords or sensitive personal information.`]}]}};var g={privacy:{heading:`13. Experimental recording and locally saved audio`,paragraphs:[`When the optional experimental recording feature is enabled, audio is captured on the user’s device and files are saved or exported to storage chosen by that user. RadioBee does not upload or host these recordings on its own servers. The user controls the saved files; device backups, storage providers, and apps used to share them may process copies under their own terms and settings.`,`Recordings may contain copyrighted broadcasts or personal information carried in a programme. The person making a recording is responsible for its lawful creation, retention, protection, deletion, and any subsequent sharing or use.`]},terms:{heading:`16. Experimental recording feature and user responsibility`,paragraphs:[`The optional audio recording capability is an experimental testing feature, provided to evaluate local audio capture, saving, conversion, and device compatibility. It is not a licensed recording service, a guarantee of uninterrupted capture or file recovery, or permission to record any third-party broadcast.`,`The person who chooses to record is solely responsible for starting the recording, choosing what to retain or share, securing any permissions required from broadcasters or other rights holders, and complying with copyright, privacy, broadcaster terms, and applicable laws. Do not record, copy, distribute, or otherwise use content where those activities are prohibited.`,`RadioBee, its owner, developers, contributors, and operators do not initiate, direct, supervise, host, or distribute recordings made by users. To the maximum extent permitted by applicable law, they disclaim responsibility and liability for recordings created, retained, shared, or misused by a user, including claims arising from that user’s conduct. Nothing in this notice excludes or limits responsibility that cannot legally be excluded.`]},"copyright-policy":{heading:`10. User-initiated experimental recordings`,paragraphs:[`The optional recording capability is provided for testing on-device audio capture and export. Its availability does not give users any licence or authorization to record, reproduce, distribute, publish, or commercially exploit radio broadcasts or other copyrighted material.`,`Any recording is initiated and controlled by the individual user, who is solely responsible for obtaining required permissions and complying with applicable rights, laws, and broadcaster restrictions. RadioBee, its owner, and its operators are not the maker or distributor of user recordings and, to the extent permitted by law, do not accept liability for unauthorized recording or use by individuals. Mandatory legal responsibilities and rights remain unaffected.`]}};var u={en:h,ta:d,sa:p};var m={en:g,ta:c,sa:l};function w(e,r,i=`en`){let a=i===`ta`||i===`sa`?i:`en`,o=u[a][e],t=r?m[a][e]:void 0;return t?m$1(l$1({},o),{sections:[...o.sections,t]}):o}var k=[{path:`/privacy`,label:`Privacy Policy`},{path:`/terms`,label:`Terms & Conditions`},{path:`/copyright-policy`,label:`Copyright & Removal`},{path:`/contact`,label:`Contact Us`}];export{w as n,y as r,k as t};